P.entries["item:fragments-of-rok-alim"] = {n="Fragments of Rok'Alim",s="Fragments of Rok'Alim sunt ramasitele de piatra sfaramata ale unui primordial elemental al pamantului, care cutreiera canioanele din Thousand Needles. Duceti la Dorn Plainstalker, in Weathered Nook, ele sunt o dovada fizica de netagaduit ca un razboinic a invins singur, in lupta, o groaza straveche.",h="Fragments of Rok'Alim sunt ramasitele de piatra sfaramata ale unui primordial elemental al pamantului, care...",kw={"dorn plainstalker","elementar","fragmente","zdrobitor","rok'alim","incercare de putere","thousand needles","weathered nook"},ang={["class:Shaman"]="Rok'Alim intruchipeaza un stravechi spirit al pamantului, legat de lume cu mult inaintea pactelor samanice moderne, iar firea sa neclintita ofera un subiect de studiu fascinant despre tenacitatea elementala pura.",["race:Tauren"]="Infruntarea ramasitelor persistente ale trecutului primordial al lui Azeroth se potriveste indeaproape cu traditiile taurenilor, care pun la incercare armonia, rezistenta si forta personala in fata celor mai primejdioase incercari ale tinutului."},sec={{t="Ramasitele unei puteri stravechi",b="In timp ce majoritatea elementarilor au disparut de pe Azeroth dupa alungarea Old Gods, cativa au avut suficienta putere bruta pentru a dainui la suprafata fara sa fie invocati prin magie muritoare. Rok'Alim the Pounder este unul dintre acesti supravietuitori, ratacind prin campiile canionului de la sud de drumul principal. Centaurii din zona il recunosc dupa bubuiturile tunatoare ale pumnilor sai de piatra, care zdrobesc orice lucru destul de nesabuit incat sa-i iasa in cale. Doborarea acestei relicve vii a lumii primordiale lasa in urma bucati zimtate de roca densa si insufletita - un trofeu demn sa dovedeasca o forta fizica fara egal."},{t="Incercarea puterii",b="Pentru pustnicul tauren Dorn Plainstalker, recuperarea fragmentelor este componenta decisiva a Test of Strength. Ca parte a unei serii de rituri spirituale si martiale desfasurate sus, in Weathered Nook, incercarea cere ca un initiat sa infrunte o entitate cu o forta bruta neclintita. Predarea daramaturilor zdrobite ale lui Rok'Alim dovedeste ca un aventurier are curajul si forta fizica necesare pentru a supravietui celor mai cumplite primejdii din Kalimdor."}},faq={{q="Ce sunt Fragments of Rok'Alim?",a="Sunt ramasitele de piatra sfaramate ale lui Rok'Alim the Pounder, un stravechi elementar al pamantului care cutreiera canioanele din nord-vestul tinutului Thousand Needles. Ele dovedesc infrangerea elementarului.",al={"fragmentele lui Rokalim","ce sunt fragmentele lui Rokalim","piatra lui Rokalim"}},{q="Cine vrea aceste fragmente de piatra?",a="Dorn Plainstalker, un tauren care ofera misiuni si locuieste la Weathered Nook, sus, pe stancile canionului din Thousand Needles, cere fragmentele pentru a incheia Test of Strength.",al={"cine primeste fragmentele lui Rokalim","preda fragmentele lui Rokalim","misiunea lui Dorn Plainstalker"}},{q="De ce este Rok'Alim important?",a="Spre deosebire de majoritatea elementarilor moderni, care trebuie evocati de mage muritori, Rok'Alim a ramas in lume inca din vremea Old Gods. Triburile Centaur din canioane i-au dat numele de 'Zdrobitorul', din cauza zgomotului asurzitor pe care il fac pumnii sai cand isi zdrobesc prada.",al={"de ce este Rokalim special","istoria lui Rokalim","cine este Rokalim the Pounder"}},{q="Unde poate fi gasit Rok'Alim?",a="Rok'Alim cutreiera bazinul de nord-vest din Thousand Needles, mergand spre sud de drumul principal al regiunii, printre turlele de gresie.",al={"locatia lui rokalim","gaseste-l pe rokalim the pounder","unde apare rokalim"}}},fx={ab6946f8={q="De unde provin Fragments of Rok'Alim?",a="Aceste fragmente sunt bucati sfaramate din Rok'Alim the Pounder, un elemental de piatra urias care rataceste pe fundul canionului din nord-vestul regiunii Thousand Needles. Spre deosebire de elementalii invocati de vrajitori muritori, Rok'Alim este un supravietuitor stravechi din era Old Gods, inzestrat cu destula putere innascuta pentru a ramane legat de lume si dupa caderea stapanilor sai. Bucatile nu au fost faurite de maini muritoare, ci desprinse direct din trupul sau viu de piatra.",al={"originea fragmentelor rokalim","de unde provin fragmentele rokalim","cine a facut fragmentele rokalim"}}},fp="21,278,28.570.0,18.449.0,35.188.0,32.176.0,28.253.0,24.131.0"}
P.entries["item:frostwolf-banner"] = {n="Frostwolf Banner",s="Frostwolf Banner este un steag tribal ascuns in adancurile pesterii Wildpaw din Alterac Valley. Recrutii Hoardei sunt trimisi sa-l recupereze ca ritual stravechi de initiere, menit sa le trezeasca spiritul razboinic si sa le castige prima insemna de clan.",h="Frostwolf Banner este un steag tribal ascuns in adancurile pesterii Wildpaw din Alterac Valley.",kw={"alterac valley","stindardul Frostwolf","gnolli","insemn","terenuri de incercare","warmaster laggrond","wildpaw cavern"},ang={["faction:Horde"]="Recuperarea acestui stindard marcheaza ceremonia de initiere prin sange a unui razboinic si primirea sa in legendarul clan Frostwolf, sub indrumarea Warmaster Laggrond.",["race:Orc"]="Pentru orci, recuperarea stindardului de clan pierdut de la gnolii salbatici onoreaza mostenirea clanului Frostwolf si mostenirea stramoseasca a lui Thrall din muntii Alterac."},sec={{t="Un ritual de trecere",b="Pentru razboinicii Horde care ajung in Alterac Valley, castigarea unui statut adevarat in clanul Frostwolf incepe cu o incercare de indarjire. Warmaster Laggrond trimite recruti noi spre sud, in coridoarele umede si ostile din Wildpaw Cavern, un salas plin de gnolli teritoriali. Sa ajunga la stindardul ascuns in adancuri si sa se intoarca fara sa-l fi rupt demonstreaza curajul, dovedeste ca furia razboinica s-a trezit in ei si le aduce insemnul initiatului Frostwolf."}},faq={{q="De ce se afla Frostwolf Banner intr-o pestera de gnolli?",a="Warmaster Laggrond si clanul trateaza in mod intentionat locatia stindardului din Wildpaw Cavern ca pe o proba de initiere. Patrunderea pe teritoriul gnoll ii obliga pe noii luptatori sa scape de complacere, sa infrunte pericolul si sa-si trezeasca spiritul razboinic.",al={"de ce este steagul in Wildpaw","gnollii au un steag","locatia steagului Frostwolf"}},{q="Cui ii returnez Frostwolf Banner?",a="Steagul trebuie inapoiat Warmaster Laggrond in Alterac Valley. Predarea lui il primeste oficial pe novice in randurile Frostwolf si ii aduce o insemna a statutului.",al={"cine vrea steagul Frostwolf","predarea steagului pentru misiune","steagul lui Laggrond"}},{q="De ce arata neobisnuit stindardul pentru o emblema Frostwolf?",a="Desi Laggrond il recunoaste drept standardul unei probe de clan, marcajele sale vizuale seamana cu insemne tribale mai vechi, inclusiv cu simboluri asociate clanurilor orci timpurii din vechea Horde.",al={"simbolul si steagul Twilight Hammer","steagul pare gresit","modelul steagului Frostwolf"}}},fx={cf6c63b1={q="Ce este Frostwolf Banner?",a="Frostwolf Banner este un stindard tribal care reprezinta clanul Frostwolf in Alterac Valley. Desi insemnul de pe el seamana, intr-un mod straniu, mai degraba cu simbolurile stravechi ale clanului decat cu blazonul sau obisnuit, ramane un simbol cinstit al prezentei si autoritatii clanului in valea inghetata.",al={"ce este steagul Frostwolf","povestea steagului Frostwolf","despre steagul Frostwolf"}},["518ec450"]={q="De ce vrea Warmaster Laggrond sa fie recuperat Frostwolf Banner?",a="Warmaster Laggrond le cere tuturor noilor veniti care vor sa lupte alaturi de Frostwolves in Alterac Valley sa treaca printr-un ritual de lupta. Recuperarea stindardului din adancul pesterii Wildpaw, pline de gnolli, iti dovedeste curajul, iti trezeste spiritul razboinic si iti aduce insemnul unui initiat al clanului.",al={"de ce sa recuperez steagul Frostwolf","de ce vrea Laggrond steagul","scopul steagului Frostwolf"}}},fp="16,231,17.460.0,48.235.0,40.179.0,57.180.0"}
