P.entries["item:garrick-s-head"] = {n="Garrick's Head",s="La podgoriile din Northshire, capul retezat al lui Garrick Padfoot dovedeste ca ucigasul este mort. Autoritatile de la Northshire Abbey au nevoie de el pentru a plati recompensa.",h="La podgoriile din Northshire, capul retezat al lui Garrick Padfoot dovedeste ca ucigasul este mort.",kw={"recompensa","Deputy Willem","Elwynn Forest","Garrick Padfoot","capul lui Garrick","Northshire Abbey","Northshire Valley"},ang={["class:Rogue"]="Ca rogue, eliminarea lui Padfoot le arata derbedeilor locali ca talharia va fi intampinata de lame profesioniste, aducatoare de moarte.",["race:Human"]="Ca Human, a lua capul lui Padfoot inseamna sa dai o prima lovitura impotriva faradelegii care se raspandeste prin Elwynn Forest."},sec={{t="Sfarsitul unui bandit",b="Garrick Padfoot si banda sa i-au hartuit timp de saptamani pe fermierii si negustorii din Northshire Valley. Cu apararea din Stormwind intinsa la maximum, Garrick si-a facut ascunzatoare intr-o coliba de langa podgorii si jefuia negustorii aflati in trecere. Garzile locale erau ocupate cu kobolds si banditii Defias, asa ca Deputy Willem a oferit o recompensa pentru moartea haiducului. Cauta pe cineva dispus sa-l ucida pe Garrick si sa aduca o dovada."}},faq={{q="Cine a fost Garrick Padfoot?",a="Garrick Padfoot a fost un talhar care teroriza fermierii, muncitorii din vii si negustorii calatori din Northshire Valley. Si-a ridicat un avanpost alaturi de banda lui la est de Northshire Abbey, dincolo de rau.",al={"cine este garrick","povestea lui garrick padfoot","cine a fost padfoot"}},{q="De ce este nevoie de un cap taiat pentru a revendica recompensa?",a="Deputy Willem si autoritatile din Northshire cer dovada mortii lui Garrick inainte de a plati recompensa.",al={"de ce capul lui","dovada mortii","de ce sa iei capul lui Garrick"}},{q="Unde se ascundea Garrick Padfoot?",a="Padfoot s-a ascuns intr-o casuta de lemn la est de Northshire Abbey, dincolo de podul de peste rau, langa podgoriile din Northshire.",al={"unde este Garrick","locatia colibei lui Garrick","unde il gasesc pe Garrick Padfoot"}},{q="Cine plateste recompensa pentru capul lui Garrick?",a="Adjunctul Willem a pus recompensa si o plateste cand primeste capul lui Garrick. Este stationat chiar in fata intrarii in Northshire Abbey.",al={"cine vrea capul lui Garrick","preda capul lui Garrick","cine a predat capul lui Garrick"}}},fx={cb1a40d1={q="Ce este Garrick's Head?",a="Acest cap retezat este dovada macabra a mortii lui Garrick Padfoot, un talhar notoriu care a terorizat fermierii si negustorii din Northshire Valley. Aducerea acestui trofeu inapoi la abatie confirma ca banda lui de talhari si-a pierdut capetenia.",al={"ce este capul lui Garrick","obiectul capul lui Garrick","cui ii apartine acest cap"}},["79b2de99"]={q="De unde provine Garrick's Head?",a="Il obtii chiar de la Garrick Padfoot. Hotul si-a asezat tabara intr-o casuta aflata langa podgoriile din Northshire, peste rau, spre est, inconjurata de huligani loiali care-i pazesc prada.",al={"unde gasesti capul lui Garrick","cine lasa capul lui Garrick","sursa capului lui Garrick"}}},fp="14,153,14.393.0,24.197.0,51.103.0,33.116.0,39.134.0"}
P.entries["item:gazlowe-s-ledger"] = {n="Gazlowe's Ledger"}
P.entries["item:gem-of-anacondra"] = {n="Gem of Anacondra",s="Gem of Anacondra este una dintre cele patru nestemate ale viselor aflate in posesia conducatorilor serpenti corupti din Wailing Caverns. Purtata de Lady Anacondra, aceasta serveste drept dovada tangibila a infrangerii ei si a limitarii raspandirii Cosmarului in Barrens.",h="Gem of Anacondra este una dintre cele patru nestemate ale viselor aflate in posesia conducatorilor serpenti...",kw={"nestemata a viselor","druizi ai coltilor","Gem of Anacondra","Lady Anacondra","liderii coltilor","Nara Wildmane","Wailing Caverns"},ang={["class:Druid"]="Pentru druizii Cenarion, revendicarea acestei pietre pretioase este o datorie solemna: sa doboare o sora care si-a predat mintea si formele puterii corupatoare a Emerald Nightmare.",["race:Tauren"]="Recuperarea gemei o ajuta direct pe Nara Wildmane din Thunder Bluff, risipind viziunile intunecate care tulbura somnul celor din Shu'halo pe Elder Rise."},sec={{t="Un focar corupt",b="Cand Naralex a intrat in somnul sau adanc pentru a readuce apa si viata in tinutul arid Barrens, Emerald Nightmare i-a invadat gandurile si i-a pervertit pe cei mai apropiati discipoli. Lady Anacondra si ceilalti conspiratori au abandonat vechile traditii si au devenit Druids of the Fang, transformand scopul lor nobil de a reda viata intr-o amagire otravitoare. Gem of Anacondra este una dintre cele patru nestemate ale viselor purtate de acesti conducatori serpenti, concentrand legatura lor corupta cu Emerald Dream si ancorand cosmarul in sistemul de pesteri."},{t="Purificarea viziunii",b="Nara Wildmane si cercul de druizi Cenarion din Thunder Bluff au descoperit ca si somnul lor era tulburat de viziunile si chipurile malefice ale conducatorilor Fang. Recuperarea Gem of Anacondra - alaturi de pietrele lui Cobrahn, Pythas si Serpentis - este necesara pentru a confirma ca Lady Anacondra a fost infranta si pentru a alunga cosmarul apasator din mintile pastratorilor echilibrului din Kalimdor."}},faq={{q="Ce este Gem of Anacondra?",a="Este o nestemata a viselor purtata de Lady Anacondra, una dintre cei patru lideri ai pervertitilor Druids of the Fang, care salasluiesc in Wailing Caverns.",al={"ce este Gem of Anacondra","Gem of Anacondra","la ce foloseste Gem of Anacondra"}},{q="Cine vrea aceasta nestemata?",a="Nara Wildmane, o druid tauren aflata pe Elder Rise in Thunder Bluff, cauta nestemata alaturi de celelalte trei nestemate ale visului, pentru a-si elibera mintea de cosmaruri si a proteja Barrens.",al={"cine ia Gem of Anacondra","unde predau Gem of Anacondra","predarea Gem of Anacondra"}},{q="Unde poate fi gasita Gem of Anacondra?",a="Bijuteria este purtata de Lady Anacondra, care pandeste in galeriile subterane serpuitoare din Wailing Caverns, in centrul Barrens.",al={"de unde cade obiectul","cine lasa Gem of Anacondra","locatia lui Lady Anacondra"}},{q="De ce sunt importante nestematele viselor?",a="Cele patru nestemate se afla in mainile conducatorilor corupti ai Druids of the Fang. Strangerea lor confirma eliminarea capilor rascoalei si le frange stapanirea asupra coruptiei din Emerald Dream in aceasta regiune.",al={"de ce patru nestemate","scopul nestematelor viselor","conducatorii nestematelor Coltilor"}}},fx={["2e0de493"]={q="De unde provine Gem of Anacondra si cine a facut-o?",a="Piatra pretioasa este purtata de Lady Anacondra in adancurile din Wailing Caverns. Desi nu se stie cine a slefuit-o sau a vrajit-o, ea este una dintre pietrele visului aflate in posesia celor patru conducatori ai Druids of the Fang. Odinioara parte a unui cerc nobil dedicat vindecarii tinutului Barrens, acesti elfi ai noptii corupti canalizeaza acum in pietre viziunile lor pervertite despre Emerald Dream.",al={"originea Gem of Anacondra","cine a creat Gem of Anacondra","de unde a luat Anacondra bijuteria ei"}}},fp="16,241,17.531.0,20.388.1,29.139.0,19.183.0,40.149.0,33.205.0"}
P.entries["item:gem-of-cobrahn"] = {n="Gem of Cobrahn",s="Gem of Cobrahn este o nestemata a viselor purtata de Lord Cobrahn, unul dintre liderii corupti ai Druids of the Fang din Wailing Caverns. Este atat un punct de concentrare pentru reveriile sale corupte, cat si o dovada fizica de care Nara Wildmane are nevoie pentru a-i confirma infrangerea.",h="Gem of Cobrahn este o nestemata a viselor purtata de Lord Cobrahn, unul dintre liderii corupti ai Druids of...",kw={"nestema visului","druizii Coltilor","Gem of Cobrahn","conducatorii Coltilor","Lord Cobrahn","Nara Wildmane","Wailing Caverns"},ang={["class:Druid"]="Pentru druizii Cenarion, recuperarea Gem of Cobrahn marcheaza sfarsitul tragic, dar necesar, al unui frate cazut care a abandonat armonia naturii in favoarea Emerald Nightmare.",["race:Tauren"]="Druizii din Thunder Bluff supravegheaza atent Barrens; luarea nestematei lui Cobrahn protejeaza in mod direct campiile si terenurile de vanatoare impotriva coruperii supranaturale."},sec={{t="Un focar al viselor corupte",b="Cand druidul night elf Naralex a intrat in Emerald Dream pentru a reda viata campiilor sterpe din Kalimdor, cosmarul sau a schimonosit atat Wailing Caverns, cat si pe discipolii sai. Printre acestia se numara Cobrahn, care a parasit caile pasnice ale Cenarion Circle pentru a lua infatisarea sarpelui. Lord Cobrahn poarta una dintre cele patru nestemate ale visului, care le intaresc conducatorilor stapanirea asupra cailor navigabile subterane, si o foloseste pentru a canaliza visele schimonosite ce ameninta sa transforme Barrens intr-o mlastina otravitoare."},{t="Restabilirea echilibrului",b="In Thunder Bluff, druidul tauren Nara Wildmane este chinuit de cosmaruri trimise de druizii renegati Druids of the Fang. Pentru a curata izvoarele subterane si a ocroti Kalimdor de vedenia lor, aventurierii trebuie sa patrunda in pesteri, sa-l ucida pe Lord Cobrahn si pe cei trei complici ai sai si sa le recupereze nestematele viselor. Intoarcerea nestematei lui Cobrahn la druizii Cenarion pune capat influentei sale corupatoare asupra lui Naralex, care doarme."}},faq={{q="Ce este Gem of Cobrahn?",a="Este o nestemata a viselor aflata in posesia lui Lord Cobrahn, un druid decazut care conduce Druids of the Fang in Wailing Caverns. Ea serveste drept canal pentru puterile sale rasucite de cosmaruri.",al={"gem of cobrahn","nestemata cobrahn","ce este gem of cobrahn"}},{q="Cine vrea Gem of Cobrahn?",a="Nara Wildmane, o druida tauren aflata in Elder Rise din Thunder Bluff, cere nestemata alaturi de alte trei pentru a-i pune capat activitatii Druids of the Fang.",al={"cine are nevoie de Gem of Cobrahn","predarea nestematei Cobrahn","cine ia nestemata Cobrahn"}},{q="De cate nestemate este nevoie pentru a incheia misiunea?",a="Sunt necesare patru nestemate: Gem of Cobrahn, Gem of Anacondra, Gem of Pythas si Gem of Serpentis, fiecare fiind detinuta de unul dintre cei patru conducatori serpenti din pesteri.",al={"cate nestemate ale viselor","nestematele conducatorilor Fang","toate nestematele Fang"}},{q="Cine este Lord Cobrahn?",a="Lord Cobrahn a fost candva discipolul lui Naralex. Cand viziunea lui Naralex s-a transformat intr-un cosmar, Cobrahn si alti cativa druizi au imbratisat forma sarpelui si au intemeiat Druids of the Fang.",al={"cine este Cobrahn","povestea lui Lord Cobrahn","cobrahn"}}},fp="14,256,27.491.0,17.430.1,27.170.0,29.155.0,47.171.0,20.192.0"}
P.entries["item:gem-of-pythas"] = {n="Gem of Pythas",s="Gem of Pythas este una dintre cele patru nestemate de vis corupte, purtate de conducatorii Druids of the Fang in Wailing Caverns. Aflata in posesia lui Lord Pythas, ea alimenteaza cosmarul care rasuceste oaza subterana si ameninta Barrens.",h="Gem of Pythas este una dintre cele patru nestemate de vis corupte, purtate de conducatorii Druids of the Fang...",kw={"barrens","dream gem","druizii coltilor","gem of pythas","lord pythas","nara wildmane","wailing caverns"},ang={["class:Druid"]="Pentru druizii Cenarion, recuperarea nestematei este o indatorire sumbra, caci aceasta simbolizeaza decaderea totala a cercului interior al lui Naralex, transformat in monstruozitati serpentine.",["race:Tauren"]="Ritualurile pervertite din pesteri ameninta echilibrul fragil al regiunii Barrens, asa ca recuperarea acestor nestemate este esentiala pentru protejarea tinutului natal al shamanilor si druidilor."},sec={{t="Un vas al cosmarului",b="Cand Naralex a intrat in Emerald Dream pentru a reda viata tinutului arid Barrens, viziunea sa nobila a fost pervertita, transformandu-se intr-un cosmar viu. Cei mai devotati urmasi ai sai au cazut odata cu el, numindu-se Druids of the Fang si cautand sa transforme lumea de la suprafata intr-o jungla veninoasa. Lord Pythas poarta aceasta piatra rezonanta, una dintre cele patru geme ale viselor care ancoreaza coruptia in pesteri. Piatra serveste drept canal pentru planul lor intunecat si drept dovada pentru druizii din Thunder Bluff ca transa pervertita a lui Pythas a fost in sfarsit spulberata."}},faq={{q="La ce foloseste Gem of Pythas?",a="Nestemata este dusa la Nara Wildmane in Thunder Bluff, impreuna cu nestematele lui Cobrahn, Anacondra si Serpentis. Impreuna, acestea duc la bun sfarsit misiunea de a pune capat capeteniilor renegate din Druids of the Fang.",al={"la ce foloseste Gem of Pythas","ce sa faci cu Gem of Pythas","misiunea cu nestemata Pythas"}},{q="Cine poarta aceasta nestemata?",a="Este pazit de Lord Pythas, un Druid Night Elf cazut, care salasluieste in adancurile Wailing Caverns din Barrens.",al={"cine lasa gem of pythas","locatia pythas","de unde obtin gem of pythas"}},{q="De ce vor druidii din Thunder Bluff cristalul?",a="Nara Wildmane si druizii Cenarion din Thunder Bluff sunt bantuiti de coruptia care se revarsa din Wailing Caverns. Obtinerea gemelor dovedeste ca cei patru conducatori monstruosi au fost ucisi, oprind cosmarul sa se raspandeasca mai departe in Barrens.",al={"de ce vrea Nara nestemate","Nara Wildmane Pythas"}},{q="Exista si alte pietre pretioase de acest fel?",a="Da. Lord Pythas este unul dintre cei patru conducatori. Ceilalti - Lady Anacondra, Lord Cobrahn si Lord Serpentis - au fiecare propria nestemata a viselor, ascunsa in adancul pesterii.",al={"alte nestemate ale viselor","nestemate-colti","nestemate din Wailing Caverns"}}},fx={["3d8d64d3"]={q="Ce este Gem of Pythas?",a="Gem of Pythas este una dintre cele patru nestemate ale viselor purtate de conducatorii Druids of the Fang in Wailing Caverns. Aflata in posesia lui Lord Pythas, relicva intruchipeaza nebunia intunecata si serpentina care i-a corupt pe acesti elfi ai noptii, candva nobili, si le-a inchistat viziunile schimonosite despre Emerald Dream intr-o forma fizica.",al={"Gem of Pythas","ce este Gem of Pythas","ce este nestemata aceasta"}}},fp="13,235,25.518.0,35.209.0,21.111.0,48.259.0,35.159.0"}
P.entries["item:gem-of-serpentis"] = {n="Gem of Serpentis",s="Gem of Serpentis este o nestemata onirica purtata de Lord Serpentis, unul dintre cei patru conducatori ai Druids of the Fang din Wailing Caverns. Aceasta serveste drept canal de concentrare pentru cosmarul distorsionat care remodeleaza reteaua de pesteri si ameninta Barrens.",h="Gem of Serpentis este o nestemata onirica purtata de Lord Serpentis, unul dintre cei patru conducatori ai...",kw={"druizi ai coltilor","Gem of Serpentis","conducatorii coltilor","Lord Serpentis","Nara Wildmane","Barrens","Wailing Caverns"},ang={["class:Druid"]="Pietrele de vis purtate de Serpentis si adeptii sai intruchipeaza riscul teribil al intrarii intr-o comuniune profunda, in transa, cu Visul, fara o disciplina spirituala vigilenta.",["race:Tauren"]="Inlaturarea influentei lui Serpentis asupra acestei bijuterii contribuie la eliberarea samanilor si druidilor din Thunder Bluff de viziunile intunecate care le tulbura somnul prin Mulgore."},sec={{t="Inima visului serpentin",b="Cand somnul lui Naralex din Wailing Caverns a cazut prada Emerald Nightmare, cei mai devotati urmasi ai sai au fost pervertiti si transformati in Druids of the Fang fanatici. Lord Serpentis este unul dintre cei patru conducatori ai cabalei. La fel ca ceilalti trei, Serpentis poarta o nestemata fermecata a viselor, care le leaga vointa colectiva de viziunea corupta. Recuperarea nestematei ii curma puterea asupra ecosistemului pesterii, lovind direct in conducerea care coordoneaza coruptia raspandita prin Barrens."},{t="Dovada pentru Thunder Bluff",b="Druid-ii tauren aflati in varful Thunder Bluff's Elder Rise, in special Nara Wildmane, indura cosmaruri vii provocate de coruptia care pandeste sub savana. Recuperarea Gem of Serpentis, alaturi de cele ale lui Cobrahn, Anacondra si Pythas, ofera dovada concreta ca liderii ordinului renegat au cazut, slabind stransoarea cosmarului asupra Cenarion Circle din Mulgore."}},faq={{q="De unde provine Gem of Serpentis?",a="Nestematul este purtat de Lord Serpentis, unul dintre cei patru conducatori ai Druids of the Fang, care locuieste in adancul cursurilor de apa intortocheate din Wailing Caverns.",al={"cine lasa Gem of Serpentis","de unde obtii nestemata Serpentis","locatia nestematei Serpentis"}},{q="Care este scopul gemei?",a="Serveste drept una dintre cele patru pietre-focar folosite de conducatorii Druids of the Fang pentru a canaliza cosmarul care deformeaza oaza subterana. Nara Wildmane din Thunder Bluff o cauta ca dovada ca Lord Serpentis a fost invins.",al={"de ce am nevoie de Gem of Serpentis","la ce foloseste Gem of Serpentis"}},{q="Cine vrea toate cele patru nestemate ale visului?",a="Nara Wildmane, o Druid aflata la Elder Rise din Thunder Bluff, le cere aventurierilor sa-i aduca nestematele lui Cobrahn, Anacondra, Pythas si Serpentis, pentru a rupe stapanirea cosmarului asupra regiunii.",al={"cine ia nestematele","predarea nestematei lui Serpentis","cui se predau obiectele liderilor Fang"}},{q="Cine era Lord Serpentis inainte sa poarte acest cristal?",a="Initial, a fost discipolul lui Naralex si a intrat in caverne cu intentia de a reda viata luxurianta tinutului Barrens, dar Emerald Nightmare i-a sucit aspiratiile nobile, transformandu-le in dorinta fanatica de a remodela lumea in chip de sarpe.",al={"legenda despre lord serpentis","cine este serpentis"}}},fx={["58ca37b7"]={q="Ce este Gem of Serpentis?",a="Gem of Serpentis este una dintre cele patru nestemate ale viselor detinute de conducatorii Druids of the Fang din Wailing Caverns. Purtata chiar de Lord Serpentis, aceasta serveste drept emblema si instrument al druidilor corupti, care vor sa schimbe tinutul Barrens dupa viziunile lor intunecate.",al={"istoria Gem of Serpentis","ce este gema Serpentis","gema lui Lord Serpentis"}}},fp="16,245,29.501.0,23.375.1,42.158.0,31.226.0,30.199.0,48.227.0"}
P.entries["item:gerenzo-s-mechanical-arm"] = {n="Gerenzo's Mechanical Arm",s="Gerenzo's Mechanical Arm este membrul protetic grefat luat de la inginerul renegat Gerenzo Wrenchwhistle din Stonetalon Mountains. Serveste drept dovada de netagaduit a mortii sale pentru agentii goblini care incearca sa elimine concurenta.",h="Gerenzo's Mechanical Arm este membrul protetic grefat luat de la inginerul renegat Gerenzo Wrenchwhistle din...",kw={"brat","Cragpool Lake","Gerenzo","brat mecanic","Sputtervalve","Stonetalon","fluier-cheie","Ziz Fizziks"},ang={["profession:Engineering"]="Bratul ilustreaza mentalitatile contrastante ale celor doua traditii ingineresti: gnomii isi sacrifica de bunavoie propria biologie pentru precizia mecanica, in vreme ce goblinii prefera adaosurile externe si forta bruta de foc.",["race:Gnome"]="Gerenzo reprezinta o latura sumbra a inventivitatii gnomilor, ducand inlocuirea mecanica mult dincolo de protezele medicale obisnuite, pana la automutilarea morbida."},sec={{t="O inventie bizara",b="Gerenzo Wrenchwhistle a dus modificarea propriului corp pana la o limita grotesca, prinzandu-si roti dintate care se invart si bucati de metal direct de trupul sau aflat in declin. Asezat deasupra lacului Cragpool Lake, gnomul renegat si-a inlocuit membrele naturale cu mecanisme complicate. Cand mesterul goblin Ziz Fizziks vrea sa-l elimine pe Gerenzo pentru a-si impresiona superiorii, acest brat mecanic distinctiv este singurul trofeu suficient de aparte pentru a dovedi fara putinta de tagada moartea inginerului."},{t="Filosofie gnomica, critica goblina",b="Pentru mintea unui goblin, amputarea unui brat perfect functional doar pentru a-l inlocui cu unul mecanic nu are prea mult sens. Ziz Fizziks a remarcat, intr-un comentariu devenit celebru, ca un inginer goblin priceput ar pastra pur si simplu ambele brate biologice si si-ar monta in schimb un al treilea, mecanic. In ciuda acestei divergente filozofice, predarea membrului retezat il multumeste pe Sputtervalve si il ajuta pe Ziz sa solicite o repartizare in Gadgetzan sau Undermine."}},faq={{q="De unde provine Gerenzo's Mechanical Arm?",a="Este luat de la Gerenzo Wrenchwhistle, care supervizeaza exploatarea lemnului si lucrarile de inginerie deasupra Cragpool Lake, langa roata de apa din Stonetalon Mountains.",al={"cine lasa bratul lui Gerenzo","locatia bratului lui Gerenzo","unde gasesti bratul mecanic al lui Gerenzo"}},{q="De ce doreste Ziz Fizziks acest brat?",a="Ziz are nevoie de o dovada concludenta pentru superiorul sau, Sputtervalve, ca Gerenzo este mort. Pentru ca Gerenzo si-a modificat substantial propriul corp, bratul sau protetic unic nu poate fi reprodus sau confundat cu al altcuiva.",al={"de ce vrea Ziz un brat","predarea bratului","dovada mortii lui Gerenzo"}},{q="De ce si-a inlocuit Gerenzo propriul brat?",a="Potrivit lui Ziz Fizziks, carnea lui Gerenzo parea sa putrezeasca. Impins de disperare sau de experimentele obsesive ale gnomilor, Gerenzo si-a grefat mecanisme si si-a inlocuit membrele care cedau cu echivalente mecanice.",al={"de ce este Gerenzo un cyborg","carnea putrezita a lui Gerenzo","de ce are un brat mecanic"}}},fx={["379afa91"]={q="Ce este Gerenzo's Mechanical Arm?",a="Este proteza cibernetica rudimentara grefata direct pe trupul lui Gerenzo Wrenchwhistle, un supraveghetor gnom bolnav, care pandeste langa roata de apa de deasupra lui Cragpool Lake. In loc sa-si pastreze trupul firesc, Gerenzo si-a imbunatatit scheletul putrezit cu roti dintate si placi metalice, transformand acest membru mecanic complicat in trasatura sa cea mai usor de recunoscut.",al={"ce este bratul lui Gerenzo","obiectul brat mecanic al lui Gerenzo","bratul mecanic al lui Gerenzo"}}},fp="24,238,19.444.0,35.412.1,46.162.0,35.205.0,36.217.0"}
P.entries["item:ghost-hair-comb"] = {n="Ghost Hair Comb",s="Ghost Hair Comb este un pieptene sinistru, impletit cu suvitele spectrale ale spiritului Blind Mary. Trimis fantomei de Madame Eva, pieptenele devine un instrument al unei revelatii tragice, inainte ca parul adunat sa fie tors intr-un fir neobisnuit.",h="Ghost Hair Comb este un pieptene sinistru, impletit cu suvitele spectrale ale spiritului Blind Mary.",kw={"Blind Mary","Darkshire","Duskwood","Ghost Hair Comb","fir de par fantomatic","Madame Eva"},ang={["class:Priest"]="Reactia indurerata a lui Mary la vederea pieptenelui reflecta vanitatea muritorilor care staruie dupa moarte si profunda lor suferinta spirituala, atat de comuna printre mortii nelinistiti din Duskwood.",["profession:Tailoring"]="Firele eterice smulse din pieptene alcatuiesc un material textil neobisnuit, obtinut nu de la oi sau viermi de matase, ci tors direct din tristetea spectrala."},sec={{t="O vanitate tragica",b="Madame Eva din Darkshire trimite pieptenele spiritului bantuit Blind Mary, care locuieste intr-o casa darapanata si pustie, la marginea Duskwood. Cand i se ofera pieptenele, fantoma se da inapoi cuprinsa de groaza, confruntata pe neasteptate cu realitatea sfasietoare ca nu mai este femeia frumoasa si vie care fusese candva. Indurerata si tulburata, Mary impinge pieptenele deoparte, lasandu-l incurcat in suvite din propriul par fantomatic."},{t="Tesut din tristete",b="Dusa inapoi la Madame Eva in Darkshire, parul prins intre dintii pieptenelui serveste unui scop mult mai ezoteric. Eva aduna fibrele spectrale delicate pentru a le toarce in Ghost Hair Thread, un material mistic de mestesugarit folosit la coaserea si legarea creatiilor oculte din tinuturile intunecate ale Duskwood."}},faq={{q="Ce este Ghost Hair Comb?",a="Este un pieptene trimis de Madame Eva din Darkshire spiritului Blind Mary. Dupa ce Mary il foloseste sau il arunca, acesta prinde fire din parul ei spectral, pe care Eva le toarce apoi in Ghost Hair Thread.",al={"ghost hair comb","ce este acest pieptene","pieptenele lui eva"}},{q="De ce tipa Blind Mary si refuza pieptenele?",a="Pieptenele ii aminteste lui Blind Mary de frumusetea ei muritoare, pierduta. Primirea lui o obliga sa-si infrunte adevarata natura: o monstruozitate spectrala ingrozitoare, nu femeia frumoasa care isi aminteste ca a fost in viata.",al={"de ce tipa Blind Mary","reactia lui Blind Mary la pieptene","de ce a aruncat Mary pieptenele"}},{q="Cine vrea sa i se inapoieze pieptenele?",a="Madame Eva, clarvazatoarea si vrajitoarea de ocazie care locuieste in Darkshire, cere ca pieptenele sa-i fie adus inapoi, pentru a putea strange parul de fantoma captiv.",al={"cine vrea pieptenele","unde sa duci pieptenele","cui sa-i inapoiezi pieptenele"}},{q="La ce sunt folosite firele de par de fantoma?",a="Madame Eva toarce firele fantomatice adunate din pieptene pentru a obtine Ghost Hair Thread, un reactiv neobisnuit, necesar ritualurilor oculte si mestesugurilor din Duskwood.",al={"la ce foloseste ghost hair","ce este ghost hair thread","rolul ghost hair thread"}}},fp="15,247,15.431.0,16.300.1,28.194.0,47.202.0,28.167.0,32.157.0"}
P.entries["item:ghost-hair-thread"] = {n="Ghost Hair Thread",s="Ghost Hair Thread este un material rar, supranatural, tors de Madame Eva in Darkshire. Incarcat cu proprietati oculte puternice, se spune ca poate lega energii spirituale si chiar poate insufla viata lucrurilor fara viata. Pustnicul Abercrombie il cere pentru a-si proteja cocioaba darapanata de fantomele nelinistite.",h="Ghost Hair Thread este un material rar, supranatural, tors de Madame Eva in Darkshire.",kw={"Abercrombie","Darkshire","Duskwood","fir de par fantomatic","Madame Eva","Raven Hill","spirite"},ang={["class:Warlock"]="Capacitatea firului de a lega entitati spirituale si de a insufleti materia neinsufletita oglindeste artele intunecate ale manipularii sufletelor si legarii constructelor.",["profession:Tailoring"]="In timp ce tesatorii obisnuiti lucreaza cu lana, matase si tesatura de vrajitor, firul fantomatic al lui Madame Eva arata ca materialul poate fi tors direct din esente supranaturale pentru a pastra vraji."},sec={{t="Tesuta din lumea spiritelor",b="Tors de ghicitoarea Madame Eva din Darkshire, firul Ghost Hair Thread este mult mai mult decat un simplu material de croitorie. Potrivit lui Eva, firul spectral are numeroase insusiri oculte, de la legarea spiritelor malefice pana la insuflarea vitalitatii in obiecte neinsufletite. Natura sa eterica il face nepretuit pentru ritualuri si protectii in tinutul blestemat Duskwood."},{t="Protejatul lui Abercrombie",b="Pustnicul retras Abercrombie, care locuieste intr-o cocioaba darapanata chiar la nord de Raven Hill Cemetery, le cere calatorilor sa aduca ata din Darkshire. Sustine ca are disperata nevoie sa intinda firul de-a lungul ferestrelor si al tocului usii, ca sa impiedice strigoii ratacitori din cimitir sa-i patrunda in casa. Totusi, avand in vedere ca ata are capacitatea stranie de a coase viata in materia lipsita de viata, scopul ei ultim ramane un mister tulburator."}},faq={{q="Ce este Ghost Hair Thread?",a="Este un material arcane folosit la mestesuguri, tors de Madame Eva in Darkshire. Are proprietati oculte aparte, capabile sa lege spirite sau sa insufle viata unor lucruri neinsufletite.",al={"par de fantoma","ce este firul din parul fantomei","fir de fantoma"}},{q="De ce isi doreste Abercrombie Ghost Hair Thread?",a="Abercrombie sustine ca are nevoie de ata pentru a captusi ferestrele si usa, creand o bariera protectoare care sa tina la distanta spiritele nelinistite ce bantuie pe-afara, in apropiere de Raven Hill Cemetery.",al={"firul lui Abercrombie","de ce vrea Abercrombie fir","vraja de protectie a lui Abercrombie"}},{q="Cine face firul?",a="Madame Eva, prezicatoarea si ghicitoarea locala din Darkshire, confectioneaza si ofera firul la cerere.",al={"cine toarce firul din parul fantomelor","firul Madamei Eva"}},{q="Pot jucatorii folosi firul la croitorie?",a="Nu. In ciuda numelui si a proprietatilor sale magice, este un obiect de misiune specializat, destinat strict sa-i fie predat lui Abercrombie, si nu poate fi folosit in retetele obisnuite de mestesugarit.",al={"croitorie","pot confectiona cu fir din par fantomatic"}}},fp="17,291,24.380.0,18.431.1,26.167.0,44.178.0,21.110.0,41.166.0"}
P.entries["item:ghoul-fang"] = {n="Ghoul Fang",s="Ghoul Fangs sunt trofee macabre, recoltate de la strigoii care bantuie dumbravile si cimitirele napadite de molima din Duskwood. In Darkshire, clarvazatoarea Madame Eva le foloseste ca ingrediente esentiale pentru confectionarea talismanelor de aparare destinate calatorilor care infrunta intunericul tot mai amenintator.",h="Ghoul Fangs sunt trofee macabre, recoltate de la strigoii care bantuie dumbravile si cimitirele napadite de...",kw={"Darkshire","Duskwood","colt de ghoul","ghouls","Madame Eva","Totem of Infliction","strigoi"},ang={["faction:Alliance"]="Pentru aventurierii din Alliance care dau ajutor orasului Darkshire, aflat sub asediu, strangerea acestor colti transforma ororile din Duskwood in mijloace de supravietuire impotriva molimei care se raspandeste, asemenea Scourge."},sec={{t="Trofee ale Restless Dead",b="Padurea intunecata din Duskwood e plina de strigoi lacomi, de la devoratorii de carne care pandesc langa morminte pana la cadavrele putrezite care ratacesc prin codri. Luarea unui colt de la aceste creaturi monstruoase este o treaba sumbra si o dovada ca ai supravietuit mortilor lacomi care ameninta hotarele Darkshire."},{t="Reactivi oculti",b="Madame Eva, ghicitoarea si mistica ce locuieste in Darkshire, vede semne cumplite rotindu-se in jurul calatorilor care indraznesc sa paseasca prin Duskwood. Ea leaga esenta necrotica latenta din coltii ghulilor de degete scheletice si venin de arahnida pentru a vraji Totem of Infliction, transformand fortele intunecate ale padurii intr-un talisman protector impotriva atacurilor violente."}},faq={{q="Unde pot fi gasiti Ghoul Fangs?",a="Sunt adunate de la diverse tipuri de ghoul din Duskwood, inclusiv Plague Spreaders, Brain Eaters, Bone Chewers, Fetid Corpses, Rotted Ones si Flesh Eaters, care bantuie cimitirele si potecile pustii.",al={"unde cad coltii de ghoul","cine lasa colti de ghoul","locatia coltilor de ghoul"}},{q="Cine vrea Ghoul Fang?",a="Madame Eva, mistica din Darkshire, are nevoie de ele pentru un ritual de creare a unui talisman defensiv numit Totem of Infliction.",al={"cine are nevoie de colti de ghoul","predarea coltilor de ghoul","misiunea lui madame eva"}},{q="De ce are nevoie Madame Eva de ele?",a="Eva simte un pericol iminent pentru calatori si foloseste coltii, alaturi de degete scheletice si venin de paianjen, pentru a vraji un totem protector care ii pedepseste pe cei care-l lovesc pe purtator.",al={"de ce colti de ghoul","materiale pentru Totem of Infliction","ce face Madame Eva cu coltii"}}},fx={["7c703fef"]={q="Ce este un Ghoul Fang?",a="Un Ghoul Fang este un dinte ascutit, smuls din falca demonilor strigoi care bantuieste Duskwood. Intinati de molima necromantica si de foamea devoratoare de carne, acesti colti pastreaza o ramasita din magia intunecata care insufleteste strigoii, devenind ingrediente puternice pentru talismane de protectie si ritualuri oculte.",al={"ce este coltii de ghoul","povestea coltilor de ghoul","despre coltii de ghoul"}},["87f3f6fc"]={q="De unde provine Ghoul Fang?",a="Acesti colti provin de la diferiti ghuli strigoi care cutreiera umbrele din Duskwood, precum Plague Spreaders, Brain Eaters, Bone Chewers si Flesh Eaters. Nu sunt mestesugiti manual, ci luati direct din falcile mortilor ratacitori.",al={"originea coltilor de ghoul","de unde provin coltii de ghoul","cine lasa colti de ghoul"}}},fp="10,263,29.285.0,15.364.0,31.211.0,22.140.0,30.175.0"}
P.entries["item:ghoul-rib"] = {n="Ghoul Rib",s="Ghoul Ribs sunt recoltate de la strigoii care bantuie crangurile si cimitirele bantuite din Duskwood. Pustnicul Abercrombie sustine ca are nevoie de ele pentru a construi o efigie groteasca, menita sa alunge ororile mancatoare de carne de langa coliba sa.",h="Ghoul Ribs sunt recoltate de la strigoii care bantuie crangurile si cimitirele bantuite din Duskwood.",kw={"abercrombie","beggar's haunt","rozator de oase","darkshire","duskwood","mancator de carne","coasta de ghoul","efigie de ghoul","undead"},ang={["class:Paladin"]="Manuirea oaselor profanate ale mortilor nelinistiti este o treaba dezgustatoare, dar sa ajuti un pustnic izolat impotriva unor monstruozitati infometate se potriveste cu apararea celor vii de ororile din Duskwood.",["class:Priest"]="Legatura deformata care reanima aceste oase reflecta umbra adanca asternuta peste Duskwood, transformand satenii cazuti in scotocitori lacomi."},sec={{t="O protectie macabra",b="Padurea blestemata din Duskwood misuna de strigoi violenti, printre care ghouli infometati precum Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones si Plague Spreaders. Abercrombie, un pustnic excentric care traieste singur intr-o coliba la nord de Raven Hill Cemetery, le cere calatorilor aflati in trecere aceste oase putrezite si rezistente. Sustine ca, traind in afara protectiei Night Watch din Darkshire, este vulnerabil si ca o efigie inspaimantatoare, alcatuita din coaste de ghoul, va servi drept sperietoare si va alunga haitele de morti care dau tarcoale."},{t="Suspiciuni in jurul colibei",b="Desi strangerea partilor celor morti vii ucisi este ceva destul de obisnuit pentru supravietuirea in tinuturi ostile, fascinatia deosebita a lui Abercrombie pentru anatomia ghoulilor ridica semne de intrebare. In loc sa caute adapost in spatele palisadelor din Darkshire sau sa se bizuie pe protectii sfintite, pustnicul insista sa stranga maruntaie necromantice crude pentru a-si fortifica locuinta izolata."}},faq={{q="Ce creaturi poarta Ghoul Rib?",a="Pot fi recoltate de la diverse tipuri de ghuli din Duskwood, inclusiv Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones si Plague Spreaders. Acesti monstri bantuie prin cimitire vechi, ruine de la marginea drumului si gospodarii abandonate din toata padurea.",al={"de unde cad coastele de ghoul","ce ghoul lasa coaste","sursele coastelor de ghoul"}},{q="De ce vrea Abercrombie aceste oase?",a="Abercrombie sustine ca locuieste prea departe de Darkshire ca sa se poata bizui pe protectia Night Watch. El cere coastele pentru a construi o sperietoare sau o efigie rudimentara, care sa-i impiedice pe mortii-vii ratacitori sa-i loveasca zidurile.",al={"de ce are nevoie abercrombie de coaste","scopul efigiei macabre","ce face abercrombie cu coastele"}},{q="Chiar tin sperietorile in ciori ghouls la distanta?",a="Strigoii nu cunosc de obicei frica si sunt manati doar de foamea oarba sau de constrangeri necromantice intunecate. Ideea ca ghoul fara minte ar fugi de o sperietoare facuta din oase este neobisnuita, dar Abercrombie insista ca aceasta ii va tine casa in siguranta.",al={"functioneaza efigia","pot efigiile sa-i sperie pe Undead","se tem ghouls de sperietori de ciori"}},{q="Unde se afla coliba lui Abercrombie?",a="Abercrombie locuieste intr-o cocioaba darapanata din partea de vest a Duskwood, imediat la nord de Raven Hill Cemetery.",al={"locatia lui Abercrombie","unde se afla pustnicul","unde se predau coastele de ghoul"}}},fx={["3e8ffb18"]={q="Ce este Ghoul Rib?",a="O Ghoul Rib este exact ceea ce pare: un os luat de la strigoii putreziti si readusi la viata care bantuie Duskwood. Smulse din fiinte monstruoase precum Flesh Eaters, Brain Eaters si Bone Chewers, aceste ramasite poarta inca urma slaba a magiei infame care insufleteste mortii umblatori din aceasta padure napastuita.",al={"informatii despre coasta de ghoul","ce sunt coastele de ghoul","obiect coaste de ghoul"}},f2829c95={q="De unde provin Ghoul Ribs?",a="Aceste coaste provin direct de la diferitii ghouls care bantuie drumurile mohorate si criptele din Duskwood. Sunt ramasite scheletice naturale, nu relicve mestesugite, luate de la monstruozitati undead precum Plague Spreaders si Rotted Ones, care cutreiera tinuturile departe de relativa siguranta din Darkshire.",al={"sursa coastelor de ghoul","unde gasesc coaste de ghoul in poveste","cine a creat coastele de ghoul"}}},fp="9,237,15.545.0,27.334.1,32.255.0,38.206.0,40.237.0,37.95.0"}
P.entries["item:giant-crocolisk-skin"] = {n="Giant Crocolisk Skin",s="Giant Crocolisk Skins sunt piei groase luate de la reptilele uriase native mlastinilor din Wetlands. Tabacarii din Menethil Harbor le pretuiesc, iar recoltarea lor este o munca primejdioasa, care a mutilat mai mult de un vanator neatent.",h="Giant Crocolisk Skins sunt piei groase luate de la reptilele uriase native mlastinilor din Wetlands.",kw={"Apprentice's Duties","crocolisc","Giant Crocolisk Skin","James Halloran","Menethil Harbor","Mlastini"},ang={["class:Hunter"]="Urmarirea crocodiliscilor uriasi de-a lungul coastei invaluite in ceata pune la incercare priceperea unui vanator de a urmari bestii acvatice si de a evita sa fie tras sub apele mlastinii."},sec={{t="Un comert periculos",b="Mlastinile si caile navigabile din Wetlands adapostesc crocolisci uriasi, a caror piele este suficient de densa pentru a rezista putrezirii cauzate de umezeala mlastinilor. In Menethil Harbor, mestesugari precum James Halloran se bazeaza pe transporturi constante de piei pentru a confectiona articole din piele rezistente. Insa, pentru a jupui un crocolisc urias ajuns la maturitate, trebuie sa infrunti apele adanci si pradatorii feroce ai mlastinii, asa ca fiecare piele obtinuta este castigata cu greu."},{t="Nesabuinta ucenicului",b="Strangerea acestor piei groase era initial sarcina tanarului ucenic al lui Halloran. Neavand priceperea martiala necesara pentru a dobori bestii de mlastina adulte, baiatul a fost prins intr-o ambuscada pe coasta de nord. Sfasiiat de crocodilii uriasi, zace acum in grija unei moase din partea locului, care spune ca s-ar putea sa-si revina. Atacul l-a silit pe Halloran sa angajeze aventurieri cu experienta pentru a vana pradatorii si a obtine pieile necesare."}},faq={{q="La ce se folosesc Giant Crocolisk Skins?",a="James Halloran, un negustor din Menethil Harbor, face rost de ele; pretuieste pieile groase pentru confectionarea unor articole din piele rezistente, capabile sa suporte clima umeda a mlastinilor.",al={"utilizarea pielii de crocolisk","de ce sa colectezi giant crocolisk skins","la ce foloseste pielea halloran"}},{q="Unde se gasesc crocodilii care furnizeaza aceste piei?",a="Crocoliscii uriasi din Wetlands cutreiera coasta si apele mlastinoase din interior, la nord de Menethil Harbor, si se plimba prin apele putin adanci dincolo de asezarile locale ale murlocilor.",al={"locatia crocodilului urias","unde gasesti crocodili uriasi","crocodili de coasta in Mlastinile"}},{q="Ce s-a intamplat cu ucenicul lui Halloran?",a="Halloran si-a trimis ucenicul singur in mlastina sa jupoaie piei. Ucenicul a fost atacat de crocolisci uriasi si mutilat atat de grav, incat a fost lasat in grija unei moase din Menethil, care spune ca s-ar putea sa-si revina.",al={"ucenic ranit","ucenicul lui Halloran","cine si-a pierdut un picior"}},{q="Cum se compara aceste piei cu pieile crocoliskilor tineri?",a="Puii de crocolisc au pielea mai subtire si mai flexibila. Crocoliscii uriasi adulti au piei mult mai groase si rezistente, dar pentru a ucide unul este nevoie de multa experienta in lupta.",al={"piele de crocolisc tanar versus Giant Crocolisk Skin","diferenta dintre pielea de crocolisc"}}},fx={["406c8fec"]={q="Ce este Giant Crocolisk Skin?",a="Este pielea groasa si rezistenta a crocodililor uriasi care cutreiera mlastinile din Wetlands. Pretuita de pielari si mesteri pentru rezistenta si dimensiunile sale, recoltarea unei astfel de blani nu-i deloc usoara, deoarece acesti pradatori se numara printre cele mai feroce fiare care pandesc prin ape.",al={"ce este giant crocolisk skin","piele de crocodil urias","informatii despre pielea de crocolisk"}},bd43ba97={q="De unde provine Giant Crocolisk Skin si cine a facut-o?",a="Pielea se jupoaie de pe crocodiliscii uriasi din Wetlands, care traiesc in mlastinile de la nord, de-a lungul coastei, dincolo de adaposturile murlocilor. In loc sa fie fabricata de un mestesugar, trebuie luata direct de pe hoiturile acestor bestii uriase de mlastina.",al={"cine a facut giant crocolisk skin","de unde provin pieile de giant crocolisk","sursa giant crocolisk skin"}},c37602c5={q="De ce doreste James Halloran Giant Crocolisk Skins?",a="James Halloran, un mestesugar din Menethil Harbor, are nevoie de piei pentru meseria sa. Initial, l-a trimis pe tanarul sau ucenic sa le stranga, dar dupa ce baiatul a fost sfasiat de fiarele flamande si a ajuns in grija unei moase, Halloran a apelat la aventurieri incercati pentru a obtine materialele si a-si razbuna protejatul.",al={"de ce vrea halloran piei","cine vrea giant crocolisk skins","de ce sunt necesare giant crocolisk skins"}}},fp="20,242,17.419.0,22.411.1,40.181.0,56.149.0,39.226.0,52.163.0"}
P.entries["item:gloom-weed"] = {n="Gloom Weed",s="Gloom Weed este o planta bolnavicioasa, specifica solului pustiit din Tirisfal Glades, care creste de obicei pe campurile dintre Deathknell si Brill. Este cunoscuta mai ales drept planta gresita culeasa de Gordo, o monstruozitate Forsaken greoaie, care o confunda cu reactivul alchimic doom weed.",h="Gloom Weed este o planta bolnavicioasa, specifica solului pustiit din Tirisfal Glades, care creste de obicei...",kw={"abominatie","Brill","buruiana osandei","buruiana intunecata","Gordo","Maestrul Holland","Tirisfal Glades"},ang={["profession:Herbalism"]="Herboristii cu experienta pot simti prezenta plantei folosind Find Herbs, ceea ce le usureaza considerabil gasirea printre tufarisurile intunecate din Tirisfal.",["race:Undead"]="Pentru noii Forsaken care pleaca din Deathknell, adunarea Gloom Weed este o lectie rapida despre neajunsurile muncii abominatiilor si firea acra a alchimistilor din Undercity."},sec={{t="O recolta gresita",b="Rasarind in mijlocul beznei si al putreziciunii din Tirisfal Glades, Gloom Weed creste din belsug in pamantul parloaga aflat la vest de Brill si la est de Solliden Farmstead. In ciuda numelui sau sumbru, planta este relativ inofensiva si nu are efectul alchimic puternic pe care il cauta Royal Apothecary Society. Faima ei se datoreaza mai ales abominatiei Gordo, care umbla pe drum si incearca sa smulga buruieni cu mainile sale uriase si neindemanatice. Intelegand gresit poruncile stapanului, Gordo culege intruna Gloom Weed si ii convinge pe calatorii creduli sa duca manunchiuri din ea inapoi la Master Holland, in cimitirul din Brill, spre supararea nespusa a alchimistului."}},faq={{q="La ce se foloseste Gloom Weed?",a="Practic, nu are nicio valoare pentru alchimistii Forsaken. Este adunata doar fiindca abominatia Gordo o confunda cu planta doom weed, pe care i-a cerut-o stapanul sau.",al={"folosirea buruienii intunecate","la ce foloseste buruiana intunecata","cine are nevoie de buruiana intunecata"}},{q="Unde creste Gloom Weed?",a="Creste raspandita prin campurile din Tirisfal Glades, intre Brill si Deathknell, mai ales de-a lungul drumului si prin pajistile de la est de Solliden Farmstead.",al={"unde gasesc buruiana intunecata","locatia buruienii intunecate","locuri cu buruiana intunecata"}},{q="Cine este Gordo si de ce il culege?",a="Gordo este o abominatie trimisa de Master Holland sa adune reactivi. Mainile sale cusute sunt prea neindemanatice, iar mintea prea simpla, asa ca rataceste pe drumuri smulgand plante gresite si rugandu-i pe trecatori sa-l ajute.",al={"cine este Gordo","de ce culege Gordo buruieni","abominatia Gordo"}},{q="Ce voia de fapt Master Holland?",a="Maestrul Holland are nevoie de buruiana doom pentru experimentele sale din cimitirul din Brill. Cand primeste Gloom Weed, pufneste la auzul greselii si ii trimite pe calatori sa culeaga planta de care avea intr-adevar nevoie.",al={"master holland weed","de ce are nevoie holland","doom weed sau gloom weed"}}},fx={bc1ac336={q="Ce este Gloom Weed?",a="Gloom Weed este o planta salbatica obisnuita, cu aspect bolnavicios, care rasare in solul blestemat din Tirisfal Glades, mai ales de-a lungul drumurilor si pe campurile deschise dintre Brill si Deathknell. Nu are puteri magice si nici proprietati alchimice valoroase. De fapt, nu este decat o buruiana obisnuita de pe marginea drumului - echivalentul unei margarete in Tirisfal - care se intampla sa infloreasca in ciuda pustiirii tinutului.",al={"ce este iarba intunecata","lore despre Gloom Weed","planta Gloom Weed"}},defb981c={q="De ce ar vrea cineva Gloom Weed?",a="Aproape nimeni nu vrea, de fapt, Gloom Weed. Singurul motiv pentru care o strange cineva este ca Gordo, o abominatie greoaie la minte, care rataceste pe campurile de langa Brill, a inteles complet gresit instructiunile. Stapanul sau, Junior Apothecary Holland, l-a trimis sa culeaga doom weed, o planta valoroasa pentru experimentele Forsaken, dar mintea greoaie a lui Gordo a incurcat denumirile si i-a pus pe calatori sa culeaga in schimb Gloom Weed, fara nicio valoare.",al={"cine vrea buruiana intunecata","de ce sa adun buruiana intunecata","de ce sa culeg buruiana intunecata"}}},fp="10,278,18.640.0,28.177.0,27.164.0,38.220.0,38.181.0"}
P.entries["item:glowing-ember"] = {n="Glowing Ember"}
P.entries["item:glowing-fruit"] = {n="Glowing Fruit"}
P.entries["item:glowing-gem"] = {n="Glowing Gem",s="Glowing Gem este o piatra fermecata recuperata din taberele murloc de-a lungul apelor din Ashenvale. Cautata initial de cercetasul cazut Teronis, piatra este o componenta esentiala pentru reconstruirea toiagului magic creat de Dartol.",h="Glowing Gem este o piatra fermecata recuperata din taberele murloc de-a lungul apelor din Ashenvale.",kw={"Astranaar","toiag de purificare","Dartol","nestemata stralucitoare","Iris Lake","murloc","Raene Wolfrunner","Shael'dryn","Teronis"},ang={["class:Druid"]="Druizii sunt interesati de cercetarile lui Teronis privind coruptia care se raspandeste si de relicva pe care acesta spera s-o restaureze.",["race:NightElf"]="Recuperarea gemului si indeplinirea misiunii lui Teronis ii ajuta pe Sentinels sa-si onoreze cercetasul cazut si sa apere Ashenvale de coruptia care se raspandeste."},sec={{t="O relicva pierduta a lui Dartol",b="Gasita in posesia murlocilor agresivi care locuiesc langa Lake Falathim, Glowing Gem este imbibata cu energie magica latenta. Tanarul elf al noptii Teronis a plecat din Astranaar ca sa o gaseasca, cu gandul sa alcatuiasca un instrument capabil sa respinga coruptia care se infiltreaza prin padurile din Ashenvale. Desi Teronis a murit prematur langa lac, piatra insasi a ramas neatinsa printre cautatorii de prada de pe mal."},{t="Restaurarea toiagului",b="Dupa recuperarea pietrei alaturi de jurnalul lui Teronis, conducatoarea Santinelelor, Raene Wolfrunner, ii cere purtatorului sa o duca spre nord-est, la Shael'dryn, o dryada care vegheaza la un put al lunii din apropiere. Dryada detine cunostintele stravechi necesare pentru a lega Glowing Gem de celelalte componente lipsa ale toiagului creat de Dartol, asigurandu-se ca munca cercetasului cazut nu a fost in zadar."}},faq={{q="De unde provine Glowing Gem?",a="Bijuteria este purtata de murlocii care cutreiera tarmurile si apele putin adanci din jurul sanctuarului de la Lake Falathim, in vestul Ashenvale, unde a cazut Teronis.",al={"locatia pietrei pretioase stralucitoare","cine lasa piatra pretioasa stralucitoare","unde gasesc o piatra pretioasa stralucitoare"}},{q="De ce cauta Teronis aceasta nestemata?",a="Teronis cerceta metode de a curata mizeria care se raspandea in Ashenvale. Potrivit cercetarilor sale, aceasta nestemata este una dintre componentele esentiale pentru refacerea unei vergi magice concepute candva de Dartol.",al={"misiunea lui teronis","de ce voia teronis nestemata","scopul nestematei"}},{q="Cui ar trebui sa-i duc Glowing Gem?",a="Dupa ce ii arati piatra si jurnalul lui Teronis lui Raene Wolfrunner in Astranaar, du Glowing Gem spre nord-est, la driada Shael'dryn, aflata langa moonwell-ul de la est de Iris Lake.",al={"cine are nevoie de nestemata stralucitoare","predau nestemata stralucitoare","ce fac cu nestemata"}},{q="Ce este toiagul lui Dartol?",a="Este un instrument magic creat de Dartol. Componentele sale au fost imprastiate prin padure, iar Glowing Gem este necesara pentru a-l reface.",al={"toiagul lui Dartol","ce a facut Dartol"}}},fx={["464fc9d6"]={q="Ce este Glowing Gem?",a="Glowing Gem este o piatra fermecata necesara pentru a recrea toiagul facut de Dartol. Teronis a cautat-o in timpul cercetarilor sale asupra coruperii din Ashenvale, iar Raene Wolfrunner coordoneaza cautarea fragmentelor ramase din toiag.",al={"ce este gema stralucitoare","spune-mi despre gema stralucitoare","istoria gemei stralucitoare"}}},fp="11,235,22.432.0,17.368.1,37.149.0,37.201.0,37.169.0,26.138.0"}
P.entries["item:glowing-soul-gem"] = {n="Glowing Soul Gem"}
P.entries["item:glutton-shackle"] = {n="Glutton Shackle",s="Glutton Shackles sunt legaturi vrajite purtate de worgenii Moonrage Glutton din Silverpine Forest. Create de arhimagele nebun Arugal, aceste bratari canalizeaza magia pentru a-i intari vrajitoria altminteri imperfecta si a-i sustine creaturile lupine blestemate.",h="Glutton Shackles sunt legaturi vrajite purtate de worgenii Moonrage Glutton din Silverpine Forest.",kw={"Arugal","Dalar Dawnweaver","Glutton Shackle","lacomul Moonrage","Sepulcher","Silverpine","worgen"},ang={["class:Mage"]="Magii vor aprecia critica usturatoare a lui Dalar Dawnweaver la adresa tehnicii de proasta calitate a lui Arugal, caci folosirea unor carje fizice fermecate pentru a stabiliza simple vraji de transmutare si invocare este considerata un semn de vrajitorie mediocra.",["race:Undead"]="Agentii Forsaken considera ca strangerea acestor catuse este un pas esential pentru neutralizarea amenintarii worgenilor, care se apropie direct de hotarele Sepulcher."},sec={{t="Un sprijin pentru vrajitoria slaba",b="Pentru magii Forsaken initiati, worgenii salbatici care napadesc Silverpine nu sunt doar monstruozitati primitive - sunt dovada unei incompetente arcane crase. Dalar Dawnweaver, un arcanist desavarsit stationat la Sepulcher, nu simte decat dispret fata de Archmage Arugal, pe care il considera un sarlatan incompetent, nedemn de Kirin Tor. Dawnweaver a descoperit ca Arugal se baza pe relicve fermecate pentru a compensa fragilitatea vrajilor sale. Glutton Shackles, purtate de masivii Moonrage Gluttons care ratacesc prin nordul Silverpine, actioneaza ca ancore magice ce intaresc blestemul care tine fiarele in lanturi."},{t="Combustibil pentru contramasurile Forsaken",b="Pentru ca Arugal a legat vraji brute direct de aceste benzi grele de fier, ele pastreaza energie magica reziduala chiar si dupa uciderea purtatorilor. Dawnweaver le cere agentilor Forsaken aceste catuse, pentru a le studia constructia si a le extrage rezervele magice. Analizand vrajile rudimentare impregnate in metal, Forsaken spera sa dezlege misterele blestemului worgen si sa puna la cale caderea stapanului fiarelor instalat in Shadowfang Keep."}},faq={{q="Ce este Glutton Shackle?",a="O Glutton Shackle este o catusa de fier vrajita, purtata de worgenii Moonrage Glutton din Silverpine Forest. Create de Archmage Arugal, aceste bratari le ofera purtatorilor o intarire magica, pentru a compensa vrajile sale imperfecte.",al={"ce sunt Glutton Shackles","povestea lui Glutton Shackle","catuse worgen"}},{q="De ce vrea Dalar Dawnweaver Glutton Shackles?",a="Dalar Dawnweaver are nevoie de catuse pentru a analiza vrajile rudimentare ale lui Arugal si a le absorbi energia magica reziduala. Intelegand obiectele pe care le-a folosit Arugal pentru a-si stabiliza bestiile, Forsaken isi pot contracara mai bine magia.",al={"de ce sa aduni shackles","misiunea lui Dalar Dawnweaver","shackles pentru Sepulcher"}},{q="Cine faureste aceste catuse?",a="Au fost vrajiti de Archmage Arugal, un fost vrajitor din Dalaran care a invocat worgen pentru a lupta impotriva Scourge, dar si-a pierdut mintea si si-a legat creatiile de vointa sa cu ajutorul unor talismane magice.",al={"cine a facut shackles","shackles ale lui Arugal","de unde provin shackles"}},{q="Unde se gasesc creaturile care poarta aceste catuse?",a="Moonrage Gluttons cutreiera padurile si gospodariile abandonate din centrul si nordul Silverpine Forest, pandind adesea in haite alaturi de alti worgen Moonrage corupti.",al={"unde apar Gluttons","locatia lui Moonrage Glutton","catuse pentru worgenii din Silverpine"}}},fp="15,238,25.593.0,33.466.1,26.221.0,48.227.0,25.198.0,53.166.0"}
P.entries["item:glyph-of-azora"] = {n="Glyph of Azora",s="Din Tower of Azora, Theocritus foloseste Glyphs of Azora pentru a supraveghea amenintarile indepartate. Pietrele inscriptionate sporesc raza de actiune a Eye of Azora, permitandu-i sa citeasca gandurile si planurile inamicilor.",h="Din Tower of Azora, Theocritus foloseste Glyphs of Azora pentru a supraveghea amenintarile indepartate.",kw={"Glyph of Azora","Morganth","Redridge","clarviziune","Stonewatch Keep","Theocritus","Tower of Azora","turnul Ilgalar"},ang={["class:Mage"]="Ca Mage, poti folosi divinatia arcana pentru a extinde clarviziunea prin cristal, transformand-o in telepatie directionata si retransmisii senzoriale la distanta.",["faction:Alliance"]="Ca membru al Alliance, poti folosi glifele pentru a aduna informatii despre Morganth si orcii Blackrock de la Stonewatch Keep."},sec={{t="Priviri dincolo de granita",b="Theocritus urmareste puterile ostile din turnul sau din Elwynn Forest. Relicva sa de cristal, Eye of Azora, ii permite sa vada la mari distante, dar nu sa patrunda in mintea sau planurile adversarilor sai. El plaseaza pe suprafete indepartate mici focare numite Glyphs of Azora, pentru ca magia sa ajunga mai departe. Fiecare glifa ii ancoreaza puterea, ingaduindu-i sa citeasca intentiile dusmanilor si sa-si proiecteze vocea peste mile intregi, pentru a vorbi cu agentii de pe teren."},{t="Spionaj in Redridge",b="In Redridge Mountains, Theocritus plaseaza rune pe un teritoriu ostil. O fixeaza pe prima de o statuie antica a unui leu, cu vedere spre Tower of Ilgalar, unde rivalul sau rogue, vrajitorul intunecat Morganth, isi are fortareata. Cu ajutorul rune, Theocritus patrunde in mintea lui Morganth si descopera o disputa intre mage renegat si Orcs Blackrock din Stonewatch Keep, aflata in apropiere. Ca sa afle cauza, trimite o a doua runa spre inaltimile turnului de veghe intact al fortaretei, ascunsa intr-un vas de bautura aruncat."}},faq={{q="La ce foloseste Glyph of Azora?",a="Theocritus foloseste un Glyph of Azora pentru a mari raza de actiune a Eye of Azora. Asezat intr-un loc indepartat, acesta ii ancoreaza magia, astfel incat sa poata citi gandurile si planurile adversarilor si sa vorbeasca cu agentii din teren de la mari distante.",al={"la ce foloseste Glyph of Azora","de ce se foloseste Glyph of Azora","scopul Glyph of Azora"}},{q="Cine a creat Glyph of Azora?",a="Theocritus a creat Glyph of Azora. El locuieste in Tower of Azora, de-a lungul granitei estice a tinutului Elwynn Forest.",al={"cine a creat gliful","creatorul Glyph of Azora","gliful lui Theocritus"}},{q="Unde sunt amplasate Glyphs of Azora?",a="Un glif este fixat pe o statuie antica de leu care domina Tower of Ilgalar. Al doilea este ascuns intr-un borcan de bautura aruncat, in turnul de veghe intact din Stonewatch Keep.",al={"unde pun gliful","locatiile de amplasare a glifului","unde se pune gliful"}},{q="De ce spioneaza Theocritus Tower of Ilgalar?",a="Tower of Ilgalar este fortareata lui Morganth. Vrajitorul intunecat si renegat este rivalul lui Theocritus, iar gliful ii permite lui Theocritus sa-i citeasca gandurile si planurile.",al={"de ce sa-l spionezi pe Morganth","Theocritus Ilgalar","dusmania lui Morganth"}},{q="Cum ii permite gliful lui Theocritus sa vorbeasca cu oamenii?",a="Odata fixat de o suprafata indepartata, gliful ancoreaza magia lui Theocritus si ii permite sa-si proiecteze vocea peste mile intregi pentru a vorbi cu agentii din teren.",al={"glif vorbitor","vocea lui Theocritus din glif","poate gliful sa vorbeasca"}}},fx={["16152ed3"]={q="Ce este Glyph of Azora?",a="Glyph of Azora este un marcaj arcane vrajit, creat de vrajitorul Theocritus la Tower of Azora. Folosite impreuna cu focarul sau de clarviziune, Eye of Azora, aceste pietre inscriptionate servesc drept posturi de ascultare la distanta. Odata fixat pe o suprafata din apropierea unei zone de interes, un glif ii permite lui Theocritus sa patrunda in mintea si gandurile tintelor sale de la mari distante si, totodata, sa-si proiecteze vocea catre oricine se afla langa el.",al={"ce este Glyph of Azora","obiectul Glyph of Azora","spune-mi despre Glyph of Azora"}},["7c5a9e02"]={q="De ce vrea Theocritus sa plantezi Glyph of Azora?",a="Theocritus se foloseste de aceste glife pentru a desfasura spionaj profund impotriva unor adversari periculosi din Redridge. Desi Eye of Azora ii permite sa vada locuri aflate la distanta, nu poate patrunde in minti fara un canalizator in apropiere. Plasarea unei glife langa Tower of Ilgalar ii permite sa cerceteze gandurile si planurile de viitor ale rivalului sau, mage renegat Morganth, in timp ce amplasarea alteia langa Stonewatch Keep il ajuta sa dezlege conflictul lui Morganth cu orcii Blackrock.",al={"de ce sa plantez glyph of azora","de ce vrea theocritus sa fie amplasat simbolul","scopul glyph of azora"}}},fp="14,182,22.424.0,21.503.1,42.206.0,31.107.0,37.168.0,49.150.0,55.141.0"}
P.entries["item:glyphic-letter"] = {n="Glyphic Letter",s="La Northshire Abbey, Glyphic Letter ii cheama pe novicii promitatori la studiul magiei arcane. Dupa ce slujesc o vreme garnizoana, sunt convocati la etaj, la Khelden Bremen, maestrul mage al abatiei.",h="La Northshire Abbey, Glyphic Letter ii cheama pe novicii promitatori la studiul magiei arcane.",kw={"arcane","elwynn forest","glyphic letter","khelden bremen","antrenor de magi","marshal mcbride","northshire abbey"},ang={["class:Mage"]="Ca Mage, aceasta comunicare marcata te cheama la etaj pentru a incepe studiul formal al traditiilor arcane ale Alliance sub indrumarea lui Khelden Bremen.",["race:Human"]="Ca Human, incepi sa te dedici disciplinelor magice ale Stormwind odata cu aceasta convocare. De-a lungul istoriei regatului, Northshire Abbey a adapostit studenti ai artelor arcane."},sec={{t="O chemare catre arcane",b="Khelden Bremen sigileaza Glyphic Letter cu insemnul sau personal. Ucenicii vrajitori o primesc dupa ce isi dovedesc disciplina in Northshire Valley. Chemarea ii scoate din indatoririle de baza pe teren si ii introduce in instruirea magica dedicata din manastire. Bremen pune la incercare hotararea fiecarui elev inainte ca acesta sa se ocupe de arcane, cu fortele sale periculoase, examinarea neinduplecata si povara pe care o aduce."}},faq={{q="Ce este Glyphic Letter?",a="Khelden Bremen scrie si pecetluieste Glyphic Letter ca invitatie la instruire. Scrisoarea le cere aspirantilor human mages sa-l gaseasca in camerele de la etaj ale Northshire Abbey, pentru pregatire arcana oficiala.",al={"ce este aceasta scrisoare","obiectul Glyphic Letter","scrisoarea lui Khelden"}},{q="Cine trimite Glyphic Letter?",a="Khelden Bremen, instructorul de mage de la Northshire Abbey, sigileaza scrisoarea cu insemnul sau. Comandamentul garnizoanei o inmaneaza dupa ce un ucenic isi dovedeste vitejia infruntand daunatorii din apropiere.",al={"cine a scris asta","cine mi-a dat glyphic letter","expeditorul scrisorii"}},{q="Unde duc Glyphic Letter?",a="Du scrisoarea in Northshire Abbey. Intra in urma lui Marshal McBride, urmeaza coridorul din stanga, urca scarile si cauta camera din spate, unde Khelden Bremen preda artele arcane.",al={"unde sa merg","unde se afla Khelden Bremen","locatia lui Khelden"}},{q="De ce cheama Khelden tinerii magi?",a="Khelden vrea sa-ti puna la incercare hotararea. Te avertizeaza ca urmarirea magiei arcane starneste deopotriva teama si respect si presupune infruntarea unor forte puternice. Trebuie sa stie ca ai vointa de a indura o asemenea soarta.",al={"de ce ma vrea Khelden","motivul antrenorului de magi","ce vrea Khelden"}}},fx={["4321b6bd"]={q="De ce vrea Khelden Bremen ca Glyphic Letter sa-ti fie livrata?",a="Scrisoarea este o convocare oficiala si o proba de hotarare pentru magii in devenire. Pecetluita cu insemnul sau personal, nota lui Khelden Bremen descrie calea primejdioasa si descurajanta a magiei arcane, avertizandu-te despre teama si incercarile ce insotesc cautarea cunoasterii interzise. Inmanandu-ti-o, el se asigura ca esti dispus sa-ti infrunti soarta inainte de a-ti incepe pregatirea oficiala.",al={"de ce Glyphic Letter","de ce am primit Glyphic Letter","scopul lui Glyphic Letter"}}},fp="14,189,23.393.0,27.189.0,29.183.0,35.185.0,38.199.0"}
P.entries["item:glyphic-memorandum"] = {n="Glyphic Memorandum"}
P.entries["item:glyphic-scroll"] = {n="Glyphic Scroll",s="Glyphic Scroll este o chemare trimisa noilor magi Forsaken readusi la viata in Deathknell. Purtand sigiliul lui Isabella, instructoarea locala de magie arcana, ea ii cheama pe vrajitorii incepatori la biserica profanata pentru a-si desavarsi mestesugul in starea de nemoarte.",h="Glyphic Scroll este o chemare trimisa noilor magi Forsaken readusi la viata in Deathknell.",kw={"arcane","Deathknell","Glyphic Scroll","Isabella","Mage","pergament","Tirisfal"},ang={["class:Mage"]="Pergamentul este prima convocare oficiala primita de un mag Forsaken si subliniaza ca strigoimea nu-l elibereaza pe vrajitor de dependenta corupatoare de magia arcana.",["race:Undead"]="Pentru Forsaken, cunostintele arcane redobandite nu sunt doar obiect de studiu, ci o arma esentiala pentru a-si asigura suveranitatea impotriva Scourge si a dusmanilor in viata."},sec={{t="O convocare din partea Bisericii",b="Cand un mag Forsaken proaspat trezit se intoarce dupa ce a starnit macelul printre Scourge fara minte din cimitirul Deathknell, il asteapta acest mesaj sigilat. Scrisul poarta semnul lui Isabella, instructorul de magie al asezarii, iar sulul il cheama pe destinatar in sanctuarul parohial ruinat. Pentru magii abia inviati, acesta este primul indrumar in disciplina magiei arcane sub steagul Forsaken - o amintire ca, desi moartea i-a eliberat de slabiciunile muritorilor, ispitele corupatoare ale puterii magice raman la fel de staruitoare."}},faq={{q="Ce este Glyphic Scroll?",a="Este o scrisoare introductiva inmanata noilor magi Forsaken ridicati din morti in Deathknell. Purtand sigiliul personal al instructorului de magie arcana Isabella, le cere vrajitorilor aflati la inceput de drum sa se prezinte la ea in biserica orasului, pentru a-si incepe pregatirea magica.",al={"ce este acest obiect","la ce foloseste Glyphic Scroll","ce face pergamentul"}},{q="Cine trimite Glyphic Scroll?",a="Pergamentul este trimis in numele Isabellei, instructoarea de magie stationata in biserica ruinata din Deathknell. Ea se adreseaza oricarui mort viu abia ridicat care are inclinatie spre arcane.",al={"cine a scris-o","cine mi-a dat asta","expeditorul pergamentului"}},{q="De ce vrea Isabella sa antreneze noi magi Forsaken?",a="Isabella cauta suflete inrudite, care impartasesc durerea mortii si dorinta de a-si recastiga patria si destinele furate. Ea le invata sa cultive suficienta putere arcana pentru a-i distruge pe toti cei care li se opun Forsaken, avertizandu-le totodata sa nu cada prada dependentei de magie si coruperii.",al={"motivul isabella","de ce antreneaza magi"}}},fp="14,233,25.552.0,27.247.0,29.195.0,51.285.0"}
P.entries["item:glyphic-tablet"] = {n="Glyphic Tablet"}
P.entries["item:glyphs-of-summoning"] = {n="Glyphs of Summoning"}
P.entries["item:gnoam-sprecklesprocket"] = {n="Gnoam Sprecklesprocket",s="Gnoam Sprecklesprocket este o sursa de energie sofisticata, recuperata din tocatorul lui Sneed, aflat in adancurile Deadmines. Inginerii gnomi cauta aceasta componenta pentru a supraincarca masinile de foraj specializate, in incercarea indrazneata de a-si recuceri caminul pierdut, Gnomeregan.",h="Gnoam Sprecklesprocket este o sursa de energie sofisticata, recuperata din tocatorul lui Sneed, aflat in...",kw={"deadmines","gnoam sprecklesprocket","gnomeregan","gyrodrillmatic","shoni the shilent","sneed","sneed's shredder","sprecklesprocket"},ang={["profession:Engineering"]="Pinionul este o sursa de energie intacta, capabila sa alimenteze utilajele necesare pentru a fora prin granitele stancoase subterane din Gnomeregan.",["race:Gnome"]="Fiecare componenta recuperata ii aduce pe gnomii exilati mai aproape de a sapa pana la casa lor pierduta si de a alunga invazia de troggi."},sec={{t="O sursa de energie vitala",b="Descoperit intr-un tocator goblin operat in fortareata Defias, Gnoam Sprecklesprocket este o realizare exceptionala in domeniul energiei mecanice compacte. Montat adanc in masina greoaie pilotata de capetenia goblin Sneed, acest miez specializat furnizeaza suficienta energie constanta pentru a pune in miscare utilaje grele de exploatare forestiera si panze de taiere. Stabilitatea si puterea lui il fac o piesa de recuperat nepretuita printre tunelurile subterane din Westfall."},{t="Patrunderea in Gnomeregan",b="In Stormwind City, inventatoarea gnome Shoni the Shilent a remarcat tocatorul din Deadmines drept cheia unei ofensive mai ample. Fortele gnome vor sa recucereasca Gnomeregan de la hoardele de trogg care au invadat-o, dar caile subterane sigilate reprezinta un obstacol redutabil. Folosind Sprecklesprocket, Shoni intentioneaza sa alimenteze excavatoare grele cu burghie giroscopice, capabile sa foreze direct prin roca solida din jurul orasului tehnologic pierdut si sa deschida o ruta neasteptata pentru un atac subteran."}},faq={{q="Ce este Gnoam Sprecklesprocket?",a="Este o sursa de alimentare mecanica intacta, de mare putere, extrasa dintr-un tocator goblin gasit in adancurile Deadmines. Are suficienta putere pentru a pune in functiune utilaje grele de foraj subteran.",al={"sprecklesprocket","ce este acest sprocket","ce este acest obiect"}},{q="De unde provine Gnoam Sprecklesprocket?",a="Este recuperat de la Sneed's Shredder, o masina industriala de taiat lemne, manevrata de maistrul goblin Sneed in interiorul fabricilor de cherestea din Deadmines.",al={"cine il lasa in urma","cum obtii sprecklesprocket","obiect lasat de shredder"}},{q="De ce are nevoie Shoni the Shilent de el?",a="Shoni are nevoie de energia produsa pentru a alimenta excavatoarele gyrodrillmatice. Aceste masinarii sunt proiectate sa foreze prin straturile de roca subterane din Gnomeregan, pentru a le permite gnomilor Alliance-aligned sa atace troggii.",al={"de ce vrea Shoni asta","obiect de misiune pentru Shoni"}},{q="Este pinionul tehnologie goblina sau gnomica?",a="Este recuperata de la un tocator goblin functional din Deadmines, iar Shoni intentioneaza sa foloseasca sursa de alimentare in utilajele de foraj gnomice. Sursa nu precizeaza cine a proiectat initial componenta.",al={"este tehnologie goblina","dispozitiv gnom sau goblin"}}},fp="22,263,20.458.0,20.512.0,35.186.0,48.149.0,35.234.0,45.206.0"}
P.entries["item:gnoll-paw"] = {n="Gnoll Paw",s="Gnoll Paws ajung la Sentinel Hill ca dovada a unei patrule impotriva grupurilor Riverpaw pack din Westfall. People's Militia ofera recompense pentru a ajuta la protejarea fermelor locale.",h="Gnoll Paws ajung la Sentinel Hill ca dovada a unei patrule impotriva grupurilor Riverpaw pack din Westfall.",kw={"danuvin","labuta de gnoll","Patrolling Westfall","People's Militia","riverpaw","Sentinel Hill","Westfall"},ang={["class:Hunter"]="Urmarirea agresivelor Riverpaw packs pe campiile deschise din Westfall le ofera hunters o prada simpla, ajutand totodata la securizarea avanposturilor rurale.",["faction:Alliance"]="Pentru campionii Alliance, recompensele oferite de People's Militia ajuta la protejarea hambarului apusean al Stormwindului de fiare ratacitoare si bande organizate."},sec={{t="Recolta militiei",b="People's Militia apara Westfall din Sentinel Hill. In absenta armatei regale si cu coroana parca oarba la necazurile rurale, cetatenii de rand si voluntarii se confrunta cu haiduci, mecanisme nebune si gnolls Riverpaw. Captain Danuvin ofera recompense pentru dovezi ca gnolls au fost ucisi. Aducerea labelor dovedeste ca patrulele au cercetat tufarisurile, in loc sa se odihneasca sub turnul de straja."},{t="O amenintare coordonata",b="Gnollii Riverpaw din Westfall cauta hrana pe campii, dar cercetasii militiei au observat semne ca acestia se coordoneaza indeaproape cu hotii Defias din jurul Deadmines. Haitele terorizeaza fermele si ataca vagoanele de aprovizionare, ajutand banditii sa se fereasca de rezistenta locala. Aducerea labelor de gnoll contribuie la mentinerea deschisa a rutelor terestre dintre Sentinel Hill si Elwynn Forest."}},faq={{q="De ce vrea Captain Danuvin Gnoll Paws?",a="Captain Danuvin cere Gnoll Paws drept dovada unei patrule incununate de succes prin campiile din Westfall. Cu putine resurse si fara ajutor din partea coroanei, militia plateste recompense cand recruti aduc dovezi ca au ucis creaturi.",al={"de ce se aduna labe","labele de gnoll pentru danuvin","la ce folosesc labele de gnoll"}},{q="Ce gnoli lasa aceste labe?",a="Labele provin de la gnoll Riverpaw care dau tarcoale prin pajistile, dealurile si fermele parasite din Westfall.",al={"unde gasesc labele de gnoll","ce gnoll lasa labe","locatia labelor de gnoll"}},{q="Actioneaza gnolii singuri in Westfall?",a="Nu. Captain Danuvin si militia suspecteaza ca gnoll-ii Riverpaw colaboreaza cu banditi si hoti care isi au baza in Deadmines si ameninta gospodariile locale.",al={"lucreaza gnolii cu Defias","legatura dintre gnoli si Deadmines","cine comanda gnolii"}},{q="De ce nu se ocupa Stormwind de amenintarea gnollilor?",a="In mijlocul tulburarilor interne si al paraliziei politice, Stormwind a lasat in mare parte Westfall sa se descurce singur. Fermierii locali si The People's Militia duc aproape toata povara apararii tinutului.",al={"de ce nu exista o armata Stormwind","unde este armata","de ce se lupta militia cu gnolii"}}},fx={aa4b645a={q="Ce este Gnoll Paw?",a="Gnoll Paw este o mana taiata de la un gnoll Riverpaw care da tarcoale campiilor din Westfall. Pentru People's Militia aflata la Sentinel Hill, aceste trofee macabre sunt dovezi fizice incontestabile ca un aventurier a patrulat activ teritoriul si a starpit haitele agresive de gnoll care ameninta gospodariile localnicilor.",al={"ce este o laba de gnoll","obiectul laba de gnoll","ce sunt labele de gnoll"}},["96952327"]={q="De unde provin Gnoll Paws?",a="Aceste labe provin direct de la gnolii Riverpaw salbatici, raspanditi prin pasunile si fermele abandonate din Westfall. Gnolii feroci cutreiera regiunea, pradand fermierii si cooperand cu nelegiuitii, asa ca labele taiate sunt o recompensa sumbra, luata direct de la jefuitorii doborati pe campul de lupta.",al={"de unde obtin labe de gnoll","cine lasa labe de gnoll","sursa labelor de gnoll"}}},fp="9,159,21.406.0,20.372.1,41.213.0,29.98.0,40.147.1,50.195.0"}
P.entries["item:gnomeregan-gumdrop"] = {n="Gnomeregan Gumdrop",s="In timpul Hallow's End, Gnomeregan Gumdrops ajung la calatori prin intermediul gnomilor exilati. O bomboana il ajuta pe bolnavul Jesper sa sarbatoreasca la orfelinatul din Stormwind.",h="In timpul Hallow's End, Gnomeregan Gumdrops ajung la calatori prin intermediul gnomilor exilati.",kw={"bomboane","gnomeregan gumdrop","hallow's end","ironforge","jesper","stormwind","talvash del kissel"},ang={["faction:Alliance"]="Calatoresti prin comunitati Human, Dwarven si Gnomish pentru a aduna acest ingredient dulce, bucurandu-te de legaturile stranse ale Alliance in timpul sarbatorilor de sezon.",["race:Gnome"]="Desi gnomes nu au un oras recuperat al lor, dulcele lor emblematic se alatura celor din marile capitale Alliance de Hallow's End."},sec={{t="O mostra de ingeniozitate gnomica",b="In Mystic Ward din Ironforge, Talvash del Kissel le imparte calatorilor Gnomeregan Gumdrops daca ii fac jocul de Hallow's End. Hangiii din toata Alliance ofera delicatese regionale, dar gnomii exilati nu au o taverna a lor in capitala. Dezastrul radioactiv i-a alungat din regatul lor subteran, dar ei continua sa-si imparta dulciurile specifice cu Alliance."},{t="O delicatesa pentru Jesper",b="Bolnav, Jesper este tinut in orfelinatul din Stormwind, in Cathedral Square, si nu poate calatori prin continente pentru a colinda de Hallow's End. Calatorii aduna patru dulciuri regionale din capitalele Alliance, ca sa i le aduca: Gnomeregan Gumdrop, Stormwind Nougat, Ironforge Mint si Darnassus Marzipan."}},faq={{q="De unde provine o Gnomeregan Gumdrop?",a="Talvash del Kissel imparte Gnomeregan Gumdrops in Mystic Ward din Ironforge cand joci una dintre farsele sale de Hallow's End.",al={"cine ofera Gnomeregan Gumdrop","cum obtii bomboana","locatia bomboanei"}},{q="De ce nu se imparte aceasta bomboana in Gnomeregan?",a="Trogg au cucerit si iradiat Gnomeregan, silindu-i pe gnomii supravietuitori sa plece in exil. Multi locuiesc acum alaturi de dwarves in Ironforge, printre ei si Talvash del Kissel.",al={"de ce Ironforge","de ce se afla Talvash in Ironforge"}},{q="La ce se foloseste aceasta bomboana?",a="Ii duci aceasta prajitura lui Jesper, un baiat orfan bolnav de la orfelinatul din Stormwind, aflat in Cathedral Square. Este una dintre cele patru dulciuri de sarbatoare adunate pentru el de Hallow's End.",al={"ce face gumdrop","bomboane Jesper"}},{q="Ce alte delicatese sunt adunate impreuna cu acesta?",a="Jesper cere si Nuga de Stormwind, Menta de Ironforge si Darnassus Marzipan. Le aduni pe fiecare in capitala Alliance corespunzatoare.",al={"alte dulciuri","dulciuri de Hallow's End"}}},fx={["243db981"]={q="Ce este Gnomeregan Gumdrop?",a="O Gnomeregan Gumdrop este o dulceata festiva care ii reprezinta pe gnomi si se imparte de Hallow's End. Desi poarta numele minunii tehnologice pierdute din Gnomeregan, desertul este oferit de gnomii care si-au gasit refugiul in capitala dwarven, Ironforge, mai ales de mesterul Talvash del Kissel.",al={"ce este Gnomeregan Gumdrop","bomboana Gnomeregan Gumdrop","povestea bomboanei gnome Gumdrop"}}},fp="18,146,28.374.0,18.290.0,42.121.0,46.162.0,28.168.0,45.130.0"}
P.entries["item:gnomish-tools"] = {n="Gnomish Tools"}
P.entries["item:gold-dust"] = {n="Gold Dust",s="In Elwynn Forest, koboldii aduna si pastreaza fulgi de aur in mine. Cumparatorii locali platesc pentru praful de aur, in timp ce minerii cauta filoane intregi de minereu.",h="In Elwynn Forest, koboldii aduna si pastreaza fulgi de aur in mine.",kw={"Elwynn","Fargodeep","praf de aur","Goldshire","Goldtooth","Jasperlode","kobold","Remy Two Times"},ang={["class:Rogue"]="Ca rogue, poti afla cum lumea interlopa muta pulbere neprelucrata si fara urma prin intermediul unor negustori dubiosi precum Remy \"Two Times\", ascunzand averea bruta de magistratii din Stormwind.",["profession:Mining"]="Minerii cauta filoane bogate de cupru si staniu cu tarnacopul si sita. Praful de kobold sugereaza ca pasajele subterane din Elwynn ascund filoane mai bogate decat arata prospectarile obisnuite."},sec={{t="O punga plina cu resturi",b="Kobolds sapa in minele Fargodeep si Jasperlode, sub Elwynn Forest. Pastreaza pulberea de aur gasita in buzunare si saculete, in loc s-o rafineze. Negustorii ambulanti si traficantii locali vor aceste ramasite, sperand sa obtina profit fara sa plateasca taxele oficiale de topire."},{t="Piata neagra din Goldshire",b="In Goldshire, Remy \"Two Times\" le cere calatorilor sa-i aduca praf de aur recuperat. Spune ca ofera cel mai bun pret din oras si schimba monede si jetoane suspecte pe praf brut, in numele unor asociati nenominalizati. Calatorii recupereaza aurul de la koboldi, in timp ce intermediarii strang bogatii chiar de sub nasul garzilor din Stormwind."}},faq={{q="De unde provine Gold Dust?",a="Koboldii din tot Elwynn Forest poarta Gold Dust. Minerii, sapatorii de tuneluri, geomantii si conducatorul lor, Goldtooth, il aduna si il depoziteaza in timp ce sapa prin dealuri.",al={"cum obtii praf de aur","prada cu praf de aur","unde gasesti praf de aur"}},{q="In ce mine se gasesc cei mai multi kobolzi care poarta Gold Dust?",a="Kobolds purtatori de praf napadesc atat Fargodeep Mine, la sud de Goldshire, cat si Jasperlode Mine, spre nord-est.",al={"unde sunt minele","cea mai buna mina pentru praf de aur","locatiile minelor"}},{q="Cine cumpara Gold Dust in Elwynn Forest?",a="Remy \"Two Times\", un negustor dubios din fata Lion's Pride Inn din Goldshire, cumpara pungile cu Gold Dust adunate, oferind bani si jetoane primite de la asociatii sai.",al={"cine vrea pulberea de aur","Remy Two Times si pulberea de aur","preda pulberea de aur"}},{q="De ce cara kobolzii praf in loc de lingouri?",a="Kobolds nu au disciplina si infrastructura necesare pentru a topi minereul cum se cuvine. In timp ce sapa prin stanca folosind tarnacoape grosolane, praf de aur se aduna pe lucrurile lor si in pungute in care poarta mici podoabe stralucitoare.",al={"de ce au kobolzii praf","aurul kobold"}}},fx={["38570104"]={q="Ce este Gold Dust?",a="Gold Dust este alcatuita din particule mici de aur brut, pretios, extrase din mine de hoardele de kobolzi care pandesc sub Elwynn Forest. Nu este moneda rafinata sau lingou turnat, ci reziduu brut pe care kobolzii il desprind direct din filoanele bogate, in mine precum Fargodeep si Jasperlode.",al={"ce este praful de aur","obiectul praf de aur","despre praful de aur"}},["4a74ebdb"]={q="De ce vrea Remy Two Times Gold Dust?",a="Remy \"Two Times\" din Goldshire cumpara praf de aur brut pentru comertul sau si pentru asociatii sai din umbra. Kobold au putine cunostinte despre topirea lingourilor, asa ca poarta asupra lor o multime de bogatii minerale nedetectate, pe care oricine indraznet le poate lua si vinde.",al={"de ce vrea Remy praf de aur","de ce vrea praf de aur","de ce vrea Remy de doua ori praf de aur"}}},fp="9,140,22.262.0,24.319.1,31.158.0,53.109.0,36.153.0,44.214.0"}
P.entries["item:golm-fragment"] = {n="Golm Fragment",s="Golm Fragment este una dintre cele patru bucati lipsa desprinse din Goaz Stone, o relicva straveche descoperita la situl arheologic din Wetlands. Recuperat de aventurieri care se feresc de raptoarele feroce, fragmentul ii ajuta pe arheologii pitici sa reconstituie inscriptii misterioase ale Titanilor.",h="Golm Fragment este una dintre cele patru bucati lipsa desprinse din Goaz Stone, o relicva straveche...",kw={"sit de excavare","goaz stone","golm fragment","uncovering the past","wetlands","whelgar"},ang={["faction:Alliance"]="Recuperarea fragmentului ajuta Explorers' League sa puna la adapost cunostinte antice nepretuite, inainte ca situl de excavare sa fie pierdut cu totul in fata raptoarelor.",["race:Dwarf"]="Pentru dwarfi, intregirea fragmentelor din Goaz Stone este esentiala pentru a-si descoperi ascendenta Titan si istoria ascunsa ingropata in Khaz Modan."},sec={{t="O bucata din Goaz Stone",b="Golm Fragment, descoperit la locul sapaturilor din sudul Wetlands, face parte dintr-o lespede monumentala cunoscuta drept Goaz Stone. Prospector Whelgar a descoperit piatra cu putin timp inainte ca raptoarele sa alunge Explorers' League, dar a constatat ca inscriptia fusese sparta in patru locuri esentiale. Golm Fragment a fost abandonat printre pamant si lazile rasturnate cand situl a fost cotropit, ascuns intr-o cutie straveche pentru relicve, pana cand exploratori curajosi l-au putut recupera."},{t="Secretele titanilor",b="Cand este reunita cu fragmentele Ados, Modr si Neru, Golm Fragment completeaza un text enigmatic al Titanilor, care prevesteste un 'plan divin' si o 'profetie a pieirii'. Reasamblarea pietrei ii permite lui Whelgar sa descifreze randuri care fac referire la fiinte stravechi inlantuite sub pamant, confirmand ca situl adaposteste o istorie mult mai veche si mai primejdioasa decat simpla mostenire a piticilor."}},faq={{q="La ce foloseste Golm Fragment?",a="Este unul dintre cele patru fragmente de piatra de care are nevoie Prospector Whelgar la situl de excavare din Wetlands pentru a restaura Goaz Stone in timpul misiunii Uncovering the Past.",al={"golm fragment - scop","de ce este necesar golm fragment","misiunea golm fragment"}},{q="Unde poate fi gasit Golm Fragment?",a="Se gaseste printre relicve stravechi si in solul afanat raspandit prin situl de excavare infestat de raptoare din dealurile sudice ale Wetlands.",al={"locatia golm fragment","gaseste golm fragment","unde se afla golm fragment"}},{q="Ce spune Goaz Stone dupa ce este asamblata?",a="Traducerea initiala a lui Whelgar vorbeste despre un plan divin si o profetie tragica. Are nevoie de toate cele patru fragmente pentru a continua descifrarea scrierii incomplete a titanilor.",al={"traducerea lui Goaz Stone","ce scrie pe tablite","traducerea lui Whelgar"}},{q="Ce alte fragmente sunt necesare pentru a completa piatra?",a="Impreuna cu Golm, trebuie sa recuperezi fragmentele Ados, Modr si Neru pentru a asambla complet tablitele.",al={"alte fragmente de tablita","bucatile de Goaz Stone","patru fragmente"}}},fx={["523a83d7"]={q="Ce este Golm Fragment?",a="Golm Fragment este una dintre cele patru bucati lipsa desprinse din Goaz Stone, o relicva straveche descoperita la situl de excavare din Wetlands. Poarta inscriptii arhaice, care se potrivesc cu textul enigmatic al tablitei mai mari.",al={"ce este Golm Fragment","povestea Golm Fragment","ce este fragmentul Golm"}},["890266ad"]={q="De unde provine Golm Fragment si cine l-a creat?",a="Fragmentul facea initial parte din Goaz Stone, cioplita cu mult timp in urma in scrierea titanilor. A fost dezgropat in timpul sapaturii arheologice a piticilor din Wetlands, inainte ca rapitoarele ostile sa navaleasca in zona si sa-i imprastie bucatile sfaramate.",al={"cine a creat Golm Fragment","originea Golm Fragment","de unde provine Golm Fragment"}},["6695e471"]={q="De ce vrea Prospector Whelgar Golm Fragment?",a="Prospector Whelgar are nevoie de Golm Fragment, alaturi de fragmentele sale surori, pentru a asambla Goaz Stone complet. Fara acesta, textul tradus se intrerupe brusc, lasand in urma detalii esentiale despre un plan divin si o profetie sumbra.",al={"de ce are Whelgar nevoie de Golm Fragment","cine vrea Golm Fragment","de ce sa cauti Golm Fragment"}}},fp="13,266,25.462.0,21.363.1,35.155.0,37.137.0,44.157.1,52.98.0"}
P.entries["item:gordon-s-crate"] = {n="Gordon's Crate",s="Gordon's Crate este un transport greu de arme, pregatit in Undercity pentru fortele Forsaken stationate in Silverpine Forest. Este o livrare esentiala de provizii, menita sa ajunga direct la garnizoana indepartata din Sepulcher.",h="Gordon's Crate este un transport greu de arme, pregatit in Undercity pentru fortele Forsaken stationate in...",kw={"ingrijitor de lilieci","deathguard podrig","gordon's crate","gordons crate","karos razok","michael garrett","provizii din silverpine","the sepulcher","undercity"},ang={["faction:Horde"]="Livrarea demonstreaza integrarea tot mai ampla a rutelor aeriene ale Forsaken, prin care proviziile si curierii strabat rapid tinutul disputat Lordaeron.",["race:Undead"]="Fiecare transport de lame si echipament din capitala intareste granitele fragile ale tinutului de frontiera al Lady Sylvanas din Silverpine Forest."},sec={{t="Provizii pentru Silverpine",b="Pentru a mentine controlul Forsaken asupra Silverpine Forest, este nevoie de un flux constant de provizii din Undercity. Gordon's Crate contine arme menite sa intareasca apararea lui Deathguard Podrig de la Sepulcher, astfel incat santinelele avanpostului sa nu fie luate prin surprindere de worgen, de fiarele salbatice sau de ramasitele populatiei umane care pandesc prin paduri."},{t="Ruta ingrijitorului de lilieci",b="Deoarece drumurile terestre dinspre capitala sunt periculoase si lente, transporturile de valoare depind de ingrijitorii de lilieci ai Undercity. Ladita ii este inmanata lui Michael Garrett, stapanul liliecilor aflat deasupra cartierului comercial al orasului, care asigura o calatorie pe spatele unui liliac zburator dresat, inapoi la cuibul lui Karos Razok din Sepulcher."}},faq={{q="Ce se afla in Gordon's Crate?",a="Lada contine arme si provizii esentiale de lupta, trimise din Undercity pentru a intari santinelele Deathguard stationate in Silverpine Forest.",al={"continutul lazilor lui Gordon","ce contine lada"}},{q="Cine ar trebui sa primeasca Gordon's Crate?",a="Deathguard Podrig primeste lada la Sepulcher. Pentru transportul ei, trebuie sa te coordonezi cu ingrijitorul liliecilor din Undercity, Michael Garrett, ca sa aranjezi un zbor direct.",al={"cine primeste lada lui Gordon","unde trebuie dusa lada"}},{q="De ce este transportata lada cu liliac, in loc sa fie dusa pe jos de un curier?",a="Silverpine Forest ramane un tinut disputat si primejdios. Folosirea liliecilor dresati, aflati sub supravegherea unor ingrijitori precum Michael Garrett si Karos Razok, asigura un transport aerian rapid, ferit de amenintarile de pe drumurile terestre.",al={"de ce sa transporti lada pe calea aerului","calatorie cu liliacul si lada"}},{q="De ce iti cere Michael Garrett sa vizitezi mai intai Sepulcher?",a="Liliecii Forsaken se intorc instinctiv in capitala, insa, pentru a ajunge in siguranta la baze indepartate precum Sepulcher, calatorii trebuie sa stabileasca mai intai o legatura cu insotitorul local, Karos Razok, inainte ca liliecii sa poata face drumul.",al={"de ce e nevoie de ruta de zbor","cerinta zborului liliecilor"}}},fx={df26763c={q="Ce este Gordon's Crate?",a="Gordon's Crate este un transport de arme esentiale si provizii militare, depozitat in Undercity. Este pregatit special pentru a fi dus cu ajutorul unui ingrijitor de lilieci la avanpostul Forsaken izolat din Sepulcher.",al={"gordon's crate","ce este lada asta","gordons crate"}},e23fc119={q="De unde provine Gordon's Crate si cine l-a facut?",a="Lada provine din Undercity, unde Gordon a impachetat proviziile garnizoanei inainte de a aranja livrarea lor catre ingrijitorii liliecilor.",al={"de unde provine lada lui Gordon","cine a impachetat lada lui Gordon","cine a facut lada lui Gordon"}},a5301c7a={q="De ce isi doreste cineva Gordon's Crate?",a="Deathguard Podrig si soldatii stationati la Sepulcher au nevoie disperata de transport. Lada contine arme necesare pentru ca Deathguards locali care apara Silverpine Forest sa fie bine inarmati si sa nu fie luati prin surprindere de dusmani.",al={"de ce este necesara lada lui Gordon","de ce sa duc lada lui Gordon la mormant","cine are nevoie de lada lui Gordon"}}},fp="14,240,23.322.0,23.309.0,30.150.0,42.163.0,65.209.0,66.220.0"}
P.entries["item:grape-manifest"] = {n="Grape Manifest",s="La Northshire Abbey, Grape Manifest consemneaza strugurii recuperati din podgoria lui Milly Osworth dupa ce banditii au pus mana pe recolta. Fructele sunt destinate pivnitelor abatiei.",h="La Northshire Abbey, Grape Manifest consemneaza strugurii recuperati din podgoria lui Milly Osworth dupa ce...",kw={"Brother Neals","Elwynn","registru de struguri","Milly Osworth","Northshire Abbey","vie","vin"},ang={["profession:Cooking"]="Pentru bucatari, registrul arata cum recoltele de pe campuri aprovizioneaza magaziile abatiei si contribuie la hranirea comunitatii monahale.",["race:Human"]="Ca Human, poti vedea greutatile de la inceput din inima Stormwindului: chiar si viata monahala si recoltele modeste au nevoie de aparare armata impotriva proscrisilor ratacitori."},sec={{t="O inregistrare a recoltei",b="Milly Osworth ingrijeste o podgorie in Northshire Valley, unde fermele locale ajuta la aprovizionarea Northshire Abbey. Banditii Defias au pus mana pe recolta, punand in pericol rezerva de fructe proaspete si struguri pentru fermentare a abatiei. Grape Manifest consemneaza strugurii recuperati de pe campuri si cantitatea lor, astfel incat intendentii abatiei sa poata tine socoteala proviziilor si sa pregateasca butoaiele pentru fermentare."},{t="Pivnicerul manastirii",b="Brother Neals se ocupa de mancarea si bautura de la Northshire Abbey si ii place sa guste vinul abatiei in linistea clopotnitei. Lista de provizii il anunta ca urmeaza sa soseasca strugurii, ajutand la asigurarea bauturii pentru calugari si recruti in vizita. Pentru fratii abatiei, fiecare baniita salvata este o victorie pentru proviziile lor si o binecuvantare de la Holy Light."}},faq={{q="Ce este Grape Manifest?",a="Grape Manifest este un inventar intocmit de Milly Osworth, care consemneaza recolta recuperata din via ei cotropita. Acesta tine evidenta strugurilor proaspeti livrati la Northshire Abbey.",al={"ce este registrul strugurilor","obiectul registru de struguri"}},{q="Cine primeste manifestul?",a="Brother Neals primeste manifestul. El supravegheaza proviziile de hrana si vin ale abatiei si degusta adesea vinuri in turnul cu clopot din Northshire Abbey.",al={"cine primeste manifestul strugurilor","cui dau manifestul strugurilor","unde trebuie dus manifestul strugurilor"}},{q="De ce erau strugurii in pericol?",a="Tilharii Defias au navalit in Northshire Valley si au alungat-o pe Milly Osworth din via ei, punand recolta in pericol si lasand abatia fara fructe proaspete pana la interventia recrutilor.",al={"de ce a trebuit sa salvez strugurii","banditii din vie","ce s-a intamplat cu recolta lui Milly"}},{q="Ce face Brother Neals cu strugurii?",a="Brother Neals foloseste strugurii pentru a reface proviziile de hrana ale abatiei si a fermenta vin Northshire proaspat pentru fratia de acolo si aparatorii aflati in vizita.",al={"la ce se foloseste strugurele","vinul de la manastire"}}},fx={a2f30a46={q="De unde provine Grape Manifest si cine l-a facut?",a="Milly Osworth, o fermiera care lucreaza viile din Northshire Valley, intocmeste registrul. Dupa ce o ajuti sa respinga talharii Defias care i-au navalit pe ogoare si sa-si recupereze recolta, ea pregateste acest document pentru a inregistra productia salvata.",al={"cine a scris manifestul strugurilor","de unde provine manifestul strugurilor","originea manifestului strugurilor"}},cbb35726={q="De ce este necesar Grape Manifest?",a="Brother Neals administreaza proviziile de mancare si bautura ale Northshire Abbey. Milly ii trimite manifestul ca sa-l anunte ca recolta ei a fost salvata de la banditi, astfel incat podgorenii abatiei pot conta pe fructe proaspete pentru a-si stoarce vinul.",al={"de ce vrea Brother Neals registrul strugurilor","scopul registrului strugurilor","de ce este necesar registrul strugurilor"}}},fp="14,173,23.388.0,20.332.0,27.185.0,26.142.0,30.184.0,43.153.0"}
P.entries["item:gray-bear-tongue"] = {n="Gray Bear Tongue",s="O limba de urs cenusiu este un ingredient brut recoltat de la ursii salbatici care cutreiera Hillsbrad Foothills. Royal Apothecary Society din Tarren Mill o cauta ca sa o foloseasca drept componenta biologica in toxinele sale experimentale.",h="O limba de urs cenusiu este un ingredient brut recoltat de la ursii salbatici care cutreiera Hillsbrad...",kw={"apothecary lydon","big samras","elixir of suffering","gray bear tongue","hillsbrad foothills","royal apothecary society","tarren mill"},ang={["race:Undead"]="Obtinerea de componente organice de la fauna locala ajuta direct misiunea Royal Apothecary Society de a crea noi molime impotriva celor vii."},sec={{t="Cercetari de alchimie in Hillsbrad",b="Salbaticia neimblanzita din jurul Tarren Mill este bogata in fauna locala, inclusiv mai multe soiuri de ursi cenusii robusi. In timp ce pradatorii naturali reprezinta o amenintare constanta pentru calatori, Forsaken ii vad drept o sursa de ingrediente brute pentru alchimie. Apothecary Lydon studiaza vietuitoarele locale pentru a izola agenti organici puternici, folosind tesutul muscular dens si fluidele din limbile ursilor cenusii drept ingrediente de baza pentru solutii letale precum Elixir of Suffering."}},faq={{q="Cine vrea limbi de urs cenusiu?",a="Apothecary Lydon, stationat la avanpostul Forsaken din Tarren Mill, in Hillsbrad Foothills, cauta aceste limbi pentru a prepara agenti ucigasi experimentali.",al={"cine are nevoie de limbi de urs","limbile pentru Apothecary Lydon","predarea limbii de urs"}},{q="La ce foloseste Apothecary aceste limbi?",a="Lydon pune la punct o potiune letala, cunoscuta drept Elixir of Suffering, menita sa ajute la raspandirea ciumei printre populatiile umane vii din Hillsbrad. Limbile sunt unul dintre principalii agenti organici, alaturi de seva paianjenilor de muschi.",al={"de ce vrea Lydon limbi","la ce foloseste limba de urs","ingredientele Elixir of Suffering"}},{q="Ce creaturi lasa aceste limbi?",a="Pot fi recoltate de la oricare dintre ursii cenusii din zona care cutreiera Hillsbrad Foothills, inclusiv ursii cenusii obisnuiti, ursii cenusii batrani, ursii cenusii fiorosi si bestia notorie Big Samras.",al={"unde cad limbile de urs","ce ursi au limbi","ursii din Hillsbrad"}}},fx={["57051fe5"]={q="Ce este Gray Bear Tongue?",a="Este exact ceea ce pare: o limba proaspat taiata de la unul dintre ursii cenusii salbatici care ratacesc prin Hillsbrad Foothills. Desi majoritatea calatorilor nu o gasesc deloc atragatoare, alchimistii si cercetatorii din randul celor Forsaken pretuiesc tesuturile animale pentru proprietatile lor chimice specifice, atunci cand prepara amestecuri noi.",al={"ce este limba de urs cenusiu","obiectul limba de urs cenusiu","ce sunt limbile de urs cenusiu"}},["4de594f1"]={q="De unde provine Gray Bear Tongue?",a="Aceste limbi sunt recoltate direct de la ursii cenusii care cutreiera padurile si colinele din jurul Tarren Mill, in Hillsbrad Foothills. Vanatorii le pot lua de la ursi cenusii obisnuiti, exemplare batrane, variante feroce sau bestii remarcabile, precum Big Samras.",al={"sursa limbilor de urs cenusiu","de unde provin limbile de urs cenusiu","cine lasa limbi de urs cenusiu"}}},fp="16,229,32.479.0,28.151.0,47.220.0,35.192.0"}
P.entries["item:gregor-s-remains"] = {n="Gregor's Remains",s="Gregor's Remains sunt oasele recuperate ale lui Gregor Agamand, inrobit de Scourge. Candva membru al celei mai bogate dinastii din Tirisfal Glades, ramasitele sale sunt cautate de un fost lucrator al morii, dornic sa incheie o socoteala veche dincolo de mormant.",h="Gregor's Remains sunt oasele recuperate ale lui Gregor Agamand, inrobit de Scourge.",kw={"agamand","brill","coleman","Deaths in the Family","farthing","gregor","mori","ramasite","scourge"},ang={["faction:Horde"]="Eliberarea Agamand Mills da o lovitura directa ramasitelor Scourge care ameninta securitatea din Tirisfal Glades.",["race:Undead"]="Tragedia Agamand oglindeste soarta multor Forsaken: oameni de rand tradati de orgoliul nobilimii si abandonati in fata ororilor Plague-ului."},sec={{t="O mostenire a ruinarii",b="Inainte de Third War, familia Agamand detinea o avere uriasa si intinderi vaste de pamant in nordul Tirisfal Glades. Cand Scourge a invadat Lordaeron, capii familiei au ales mandria in locul fugii, fortificandu-si morile si convingandu-si muncitorii loiali sa opuna o rezistenta disperata mortilor vii. Apararea a esuat cu totul. Domeniul a fost cotropit, iar cei care au ramas sa lupte au fost macelariti si ridicati ca morti vii. Gregor Agamand a devenit inca un sclav fara minte in slujba Lich King, bantuid chiar morile pe care familia sa le stapanise candva."},{t="Pretul razbunarii",b="Pentru supravietuitorii care au scapat de sub controlul Lich King pentru a se alatura celor din Forsaken, amintirea acelei aparari fatidice ramane o rana amara. Coleman Farthing, fost muncitor la moara stationat in Brill, da vina pe aroganta celor din Agamands pentru captivitatea sufletului sau in putreziciunea eterna. Adunarea ramasitelor lui Gregor ii ofera lui Farthing o masura de razbunare personala, punand capat povestii stapanului care si-a dus familia direct spre osanda."}},faq={{q="Cine a fost Gregor Agamand?",a="Gregor Agamand a fost un membru de seama al dinastiei Agamand, cea mai bogata familie de proprietari de pamanturi din Tirisfal Glades inainte de Third War. Cand a sosit Plague of Undeath, el si familia sa au ales sa-si fortifice mosia in loc sa fuga, ceea ce a dus la macelarirea si reanimarea tuturor celor dinauntru.",al={"povestea lui gregor","cine este gregor","gregor agamand"}},{q="De ce vrea Coleman Farthing ramasitele lui Gregor's Remains?",a="In viata, Coleman Farthing a fost un muncitor la moara, angajat de Agamands. Le poarta o ura adanca acestora pentru ca si-au convins muncitorii sa ramana si sa lupte impotriva Scourge, o greseala care i-a condamnat pe toti la nemoarte. Ramasitele lui Gregor, aduse la el, reprezinta o razbunare mult amanata.",al={"de ce vrea Coleman ramasitele","ranchiuna lui Coleman Farthing","de ce sa adune oasele lui Gregor"}},{q="Unde se gasesc Gregor's Remains?",a="Ramasitele sunt recuperate de la Gregor Agamand, revenit la viata, in Agamand Mills, aflat pe dealurile nordice din Tirisfal Glades.",al={"unde il gasesc pe Gregor","locatia lui Gregor","Gregor de la Agamand Mills"}},{q="Fac cei din Agamands parte din Forsaken?",a="Nu. Spre deosebire de Forsaken, care si-au castigat libertatea sub conducerea reginei Sylvanas, Gregor Agamand si rudele sale raman slujitori fara minte, inlantuiti de vointa Scourge.",al={"gregor este forsaken","Agamands sunt Scourge","cine detine controlul asupra lui gregor"}}},fx={["6dd1de2a"]={q="Ce sunt Gregor's Remains?",a="Acestea sunt ramasitele trupesti ale lui Gregor Agamand, unul dintre mostenitorii proeminentei dinastii Agamand. Dupa ce a cazut prada Plague of Undeath, Gregor s-a ridicat ca slujitor lipsit de minte al Scourge si a bantuit ruinele morilor candva infloritoare ale familiei sale, pana cand a fost doborat definitiv.",al={"ce sunt ramasitele lui Gregor","obiectul ramasitele lui Gregor"}},["45ae8d93"]={q="De unde provin Gregor's Remains?",a="Aceste ramasite sunt tot ce a mai ramas din Gregor Agamand dupa ce a fost doborat la Agamand Mills, in vestul Tirisfal Glades. Cand Scourge a napadit Lordaeron, familia lui si-a fortificat mosia si si-a indemnat lucratorii sa lupte, dar toti au fost macelariti si ridicati apoi ca strigoi.",al={"originea ramasitelor lui Gregor","cine a creat ramasitele lui Gregor","de unde provin ramasitele lui Gregor"}}},fp="16,246,16.557.0,22.424.0,23.299.0,48.276.0,33.135.0,38.148.0"}
P.entries["item:grelin-s-report"] = {n="Grelin's Report",s="Grelin's Report este o depesa scrisa de Grelin Whitebeard, care descrie situatia trolilor Frostmane din Coldridge Valley. Incredintata unui aventurier, si nu unui ucenic novice, depesa serveste drept legatura oficiala intre cercetasii care pazesc Anvilmar si Senir Whitebeard, aflat in Kharanos.",h="Grelin's Report este o depesa scrisa de Grelin Whitebeard, care descrie situatia trolilor Frostmane din...",kw={"Coldridge Valley","Grelin Whitebeard","raportul lui Grelin","Ironforge Senate","Kharanos","Mountaineer Thalos","Senir Whitebeard"},ang={["race:Dwarf"]="Purtarea acestui raport marcheaza trecerea unui pitic de la terenurile de antrenament sigure din Coldridge la apararea mai ampla a tinutului Dun Morogh si la slujirea Ironforge.",["race:Gnome"]="Predarea mesajului lui Grelin le permite refugiatilor gnomi sa-si dovedeasca valoarea in fata cataratorilor dwarfi, traversand impreuna trecatorile montane din Dun Morogh."},sec={{t="O solie dincolo de Troggs",b="Redactat dupa ce a observat trolii Frostmane din Coldridge Valley, Grelin's Report concluzioneaza ca acestia nu reprezinta o amenintare prea mare si ca pot fi tinuti sub control de Mountaineers deja stationati acolo si de mercenari platiti din fondurile Senate. In loc sa aiba incredere in ucenicul sau neindemanatic pentru transmiterea unor informatii atat de importante, Grelin incredinteaza documentul unui calator priceput, care trebuie sa-l duca prin Coldridge Pass, infestat de troggs. Documentul serveste drept permis oficial pentru trecerea de blocada lui Mountaineer Thalos, dovedind ca purtatorul se afla intr-o misiune urgenta catre intinderile inzapezite din Dun Morogh."},{t="Zburatacind pene in Kharanos",b="Cand este inmanat lui Senir Whitebeard la Thunderbrew Distillery din Kharanos, raportul ofera actualizari esentiale de pe teren, destinate orasului Ironforge. Senir observa cu o resemnare amuzata ca fratele sau a invocat din plin numele regelui Magni Bronzebeard in text. Grelin pretinde ca actiunea a fost autorizata de rege, iar Senir se asteapta ca apelul la autoritatea regala sa starneasca nemultumire in Ironforge Senate."}},faq={{q="La ce foloseste Grelin's Report?",a="Raportul cuprinde evaluarea lui Grelin Whitebeard despre trolii Frostmane, trimisa din Coldridge Valley fratelui sau, Senir, in Kharanos. Conducerea din afara vaii este asigurata ca trolii nu reprezinta o amenintare majora si ca pot fi tinuti sub control de Mountaineerii locali si de mercenarii finantati de Senate.",al={"ce este raportul lui Grelin","de ce sa trimiti raportul","scopul raportului lui Grelin"}},{q="De ce nu poate Grelin sa-l livreze personal?",a="Grelin a ramas in Coldridge Valley, unde ii supravegheaza pe trolli. La inceput se gandise sa-si trimita ucenicul, dar calatoria primejdioasa prin tunelul infestat de troggi l-a facut sa incredinteze documentele vitale unui aventurier incercat in lupta.",al={"de ce sa nu-l predam","de ce sa-l incredintam unui aventurier"}},{q="De ce te lasa Mountaineer Thalos sa treci cu raportul?",a="Mountaineer Thalos pazeste tunelul care duce afara din Coldridge Valley, pentru a-i tine pe civili la adapost de troggii feroce. Daca ai asupra ta Grelin's Report, dovedesti ca te afli intr-o misiune urgenta pentru apararea piticilor, iar Thalos te lasa sa treci.",al={"de ce ma lasa Thalos sa trec","blocada tunelului","troggii din Coldridge Pass"}},{q="De ce este deranjat Ironforge Senate de raport?",a="Senir Whitebeard remarca faptul ca Grelin a invocat din plin numele regelui Magni in tot documentul. Trecerea peste subtilitatile diplomatice obisnuite pentru a cere atentia regelui ii infurie adesea pe birocratii din Ironforge Senate, chiar daca fratii sunt de acord ca politicienii au nevoie de un semnal de alarma.",al={"de ce e suparat Senate","a starni furia","reactia lui Senir"}}},fx={cdcce173={q="Ce este Grelin's Report?",a="Este o depesa scrisa de Grelin Whitebeard in Coldridge Valley, adresata fratelui sau, Senir Whitebeard, din Kharanos. Cuprinde observatii locale si chestiuni urgente din vale, desi Grelin a invocat numele regelui Magni Bronzebeard atat de des in paginile ei, incat a starnit controverse printre senatori, tocmai in Ironforge.",al={"ce este raportul lui grelin","raportul lui grelin"}},["9a092709"]={q="De unde provine Grelin's Report si cine l-a creat?",a="Documentul a fost redactat de Grelin Whitebeard, pe cand era detasat in Coldridge Valley. In loc sa i-l incredinteze ucenicului sau, Grelin a hotarat sa-l dea unui calator capabil, pentru a-i garanta drumul in siguranta spre est, prin tunelul plin de troggi care duce in tinuturile mai intinse din Dun Morogh.",al={"cine a scris raportul lui Grelin","de unde provine raportul lui Grelin","cine a intocmit raportul lui Grelin"}},["6be6ebf1"]={q="De ce ar vrea cineva Grelin's Report?",a="Fratele sau, Senir Whitebeard, asteapta mesajul in Kharanos pentru a-si coordona descoperirile inainte de a trimite rapoartele reunite catre Ironforge. Documentul este important si pentru tine: dovada ca te ocupi de o afacere oficiala a familiei Whitebeard este singurul motiv pentru care Mountaineer Thalos iti ingaduie trecerea prin tunelul primejdios, napadit de troggi, care iese din Coldridge Valley.",al={"de ce este necesar raportul lui Grelin","de ce vrea Senir raportul lui Grelin"}}},fp="15,291,26.564.0,29.414.0,39.279.0,36.253.0,57.230.0,50.280.0"}
P.entries["item:grelin-whitebeard-s-journal"] = {n="Grelin Whitebeard's Journal"}
